/**
 * SymbolContext — Global Pair Filter
 *
 * Provides: { symbol, setSymbol, recentSymbols, categoryFilter }
 * Default: XAU/USD (chart + watchlist canonical for gold)
 * All tabs import useSymbol() and filter content
 */

import { createContext, useContext, useState, useCallback, type ReactNode } from 'react';

const ACTIVE_SYMBOL_KEY = 'tradingos.activeSymbol';
const RECENT_SYMBOLS_KEY = 'tradingos.recentSymbols';

function loadStoredSymbol(): string {
  try {
    const s = localStorage.getItem(ACTIVE_SYMBOL_KEY);
    if (s && s.trim()) return s.trim();
  } catch { /* noop */ }
  return 'XAU/USD';
}

function loadStoredRecents(fallback: string[]): string[] {
  try {
    const raw = localStorage.getItem(RECENT_SYMBOLS_KEY);
    if (raw) {
      const arr = JSON.parse(raw) as unknown;
      if (Array.isArray(arr) && arr.length) return arr.map(String).filter(Boolean).slice(0, 10);
    }
  } catch { /* noop */ }
  return fallback;
}

export interface SymbolContextValue {
  symbol: string;
  setSymbol: (s: string) => void;
  recentSymbols: string[];
  /** Apply symbol + recents from server without re-deriving recents (cloud sync). */
  hydrateFromWorkspaceServer: (sym: string, recents: string[]) => void;
  categoryFilter: string | null;
  setCategoryFilter: (c: string | null) => void;
}

const SymbolContext = createContext<SymbolContextValue>({
  symbol: 'XAU/USD',
  setSymbol: () => {},
  recentSymbols: ['XAU/USD', 'EUR/USD', 'GBP/USD', 'BTC/USD', 'US30'],
  hydrateFromWorkspaceServer: () => {},
  categoryFilter: null,
  setCategoryFilter: () => {},
});

export function SymbolProvider({ children }: { children: ReactNode }) {
  const defaultRecents = ['XAU/USD', 'EUR/USD', 'GBP/USD', 'BTC/USD', 'US30'];
  const [symbol, setSymbolRaw] = useState(loadStoredSymbol);
  const [recentSymbols, setRecentSymbols] = useState<string[]>(() =>
    loadStoredRecents(defaultRecents),
  );
  const [categoryFilter, setCategoryFilter] = useState<string | null>(null);

  const setSymbol = useCallback((s: string) => {
    setSymbolRaw(s);
    try {
      localStorage.setItem(ACTIVE_SYMBOL_KEY, s);
    } catch { /* noop */ }
    setRecentSymbols(prev => {
      const filtered = prev.filter(x => x !== s);
      const next = [s, ...filtered].slice(0, 10);
      try {
        localStorage.setItem(RECENT_SYMBOLS_KEY, JSON.stringify(next));
      } catch { /* noop */ }
      return next;
    });
  }, []);

  const hydrateFromWorkspaceServer = useCallback((sym: string, recents: string[]) => {
    const s = String(sym || '').trim() || 'XAU/USD';
    const r = Array.isArray(recents) && recents.length
      ? recents.map(String).filter(Boolean).slice(0, 10)
      : loadStoredRecents(defaultRecents);
    setSymbolRaw(s);
    setRecentSymbols(r);
    try {
      localStorage.setItem(ACTIVE_SYMBOL_KEY, s);
      localStorage.setItem(RECENT_SYMBOLS_KEY, JSON.stringify(r));
    } catch { /* noop */ }
  }, []);

  return (
    <SymbolContext.Provider
      value={{
        symbol,
        setSymbol,
        recentSymbols,
        hydrateFromWorkspaceServer,
        categoryFilter,
        setCategoryFilter,
      }}
    >
      {children}
    </SymbolContext.Provider>
  );
}

export function useSymbol() {
  return useContext(SymbolContext);
}

/**
 * engine/adapter/engineAdapter.ts
 * ===============================
 * The ONLY layer the UI talks to (new modular engine).
 */

import type { NewsItem, NewsFilter } from '../types/news';
import type { MacroSeries, MacroFilter } from '../types/macro';
import type { AccountSummary, Position, WatchlistItem } from '../types/account';
import type { ChartData } from '../types/chart';
import type { ScannerResult, ScannerFilter } from '../types/scanner';
import type { EarningsEvent } from '../types/earnings';
import type { AnalystConsensusData, RelativePerformanceData, KeyLevelsData, SentimentShortData } from '../types/context';
import type { AxeContext, AxeMemoryItem, AxeStatus } from '../types/axe';
import type { DashboardData, HistoricalMetrics } from '../types/dashboard';
import type { BrokerAccount, BrokerTrade, JournalAnalytics, JournalLabel, TradeHistoryQuery } from '../types/broker';

import { NewsService } from '../services/newsService';
import { ContextService } from '../services/contextService';
import { IntelService } from '../services/intelService';
import { MacroService } from '../services/macroService';
import { AccountService } from '../services/accountService';
import { ChartService } from '../services/chartService';
import { ScannerService } from '../services/scannerService';
import { EarningsService } from '../services/earningsService';
import { AxeService } from '../services/axeService';
import { DashboardService } from '../services/dashboardService';
import { BrokerTradesService } from '../services/brokerTradesService';
import type { TradingAdapterFacade } from './tradingAdapterFacade';

export class EngineAdapter implements TradingAdapterFacade {
  private readonly newsService: NewsService;
  private readonly contextService: ContextService;
  private readonly intelService: IntelService;
  private readonly macroService: MacroService;
  private readonly accountService: AccountService;
  private readonly chartService: ChartService;
  private readonly scannerService: ScannerService;
  private readonly earningsService: EarningsService;
  private readonly axeService: AxeService;
  private readonly dashboardService: DashboardService;
  private readonly brokerTradesService: BrokerTradesService;

  constructor(
    newsService: NewsService,
    contextService: ContextService,
    intelService: IntelService,
    macroService: MacroService,
    accountService: AccountService,
    chartService: ChartService,
    scannerService: ScannerService,
    earningsService: EarningsService,
    axeService: AxeService,
    dashboardService: DashboardService,
    brokerTradesService: BrokerTradesService,
  ) {
    this.newsService = newsService;
    this.contextService = contextService;
    this.intelService = intelService;
    this.macroService = macroService;
    this.accountService = accountService;
    this.chartService = chartService;
    this.scannerService = scannerService;
    this.earningsService = earningsService;
    this.axeService = axeService;
    this.dashboardService = dashboardService;
    this.brokerTradesService = brokerTradesService;
  }

  async news(symbol?: string, filters?: Omit<NewsFilter, 'symbol'>): Promise<NewsItem[]> {
    return this.newsService.getNews({ symbol, ...filters });
  }

  getAnalystConsensus(symbol: string): Promise<AnalystConsensusData | null> {
    return this.contextService.getAnalystConsensus(symbol);
  }

  getRelativePerformance(symbol: string): Promise<RelativePerformanceData | null> {
    return this.contextService.getRelativePerformance(symbol);
  }

  getKeyLevels(symbol: string): Promise<KeyLevelsData | null> {
    return this.contextService.getKeyLevels(symbol);
  }

  getSentimentShort(symbol: string): Promise<SentimentShortData | null> {
    return this.contextService.getSentimentShort(symbol);
  }

  getCorporateJets() {
    return this.intelService.getCorporateJets();
  }

  getVesselStream() {
    return this.intelService.getVesselStream();
  }

  async macroSeries(key: string, range?: MacroFilter['range']): Promise<MacroSeries> {
    return this.macroService.getSeries(key, { range });
  }

  async listMacroSeries(): Promise<{ key: string; name: string; unit: string; frequency: string }[]> {
    return this.macroService.listAvailableSeries();
  }

  async getAccountSummary(userId: string): Promise<AccountSummary> {
    return this.accountService.getSummary(userId);
  }

  async getOpenPositions(userId: string): Promise<Position[]> {
    return this.accountService.getOpenPositions(userId);
  }

  async getWatchlist(userId: string): Promise<WatchlistItem[]> {
    return this.accountService.getWatchlist(userId);
  }

  async getChart(symbol: string, timeframe: string, limit?: number): Promise<ChartData> {
    return this.chartService.getChart(symbol, timeframe, limit);
  }

  async getScannerResults(filter?: ScannerFilter): Promise<ScannerResult[]> {
    return this.scannerService.scan(filter);
  }

  async getEarningsCalendar(from: string, to: string): Promise<EarningsEvent[]> {
    return this.earningsService.getEarningsCalendar(from, to);
  }

  async getAxeContext(symbol: string, timeframe: string, userId: string): Promise<AxeContext> {
    return this.axeService.getContext(symbol, timeframe, userId);
  }

  async getAxeMemory(userId: string, symbol?: string): Promise<AxeMemoryItem[]> {
    return this.axeService.getMemory(userId, symbol);
  }

  async getAxeStatus(userId: string): Promise<AxeStatus> {
    return this.axeService.getStatus(userId);
  }

  async getDashboard(): Promise<DashboardData> {
    return this.dashboardService.getDashboard();
  }

  async getMetricsHistory(timeframe: '1H' | '24H' | '7D' | '30D'): Promise<HistoricalMetrics> {
    return this.dashboardService.getHistory(timeframe);
  }

  async getEngineStatus(): Promise<{ status: 'healthy' | 'degraded' | 'critical'; message: string }> {
    return this.dashboardService.getQuickStatus();
  }

  listBrokerAccounts(userId: string): Promise<BrokerAccount[]> {
    return this.brokerTradesService.listAccounts(userId);
  }

  createBrokerAccount(
    userId: string,
    args: { label: string; mt5Login?: string; mt5Server?: string },
  ): Promise<{ account: BrokerAccount; linkToken: string }> {
    return this.brokerTradesService.createAccount(userId, args);
  }

  async setActiveAccount(userId: string, accountId: string | null): Promise<{ ok: true }> {
    await this.brokerTradesService.setActiveAccount(userId, accountId);
    return { ok: true };
  }

  getTradeHistory(
    userId: string,
    query: TradeHistoryQuery,
  ): Promise<{ trades: BrokerTrade[]; labelsByTradeId: Record<string, { label: JournalLabel; note?: string | null; updatedAt: string }> }> {
    return this.brokerTradesService.getTradeHistory(userId, query) as any;
  }

  async labelTrade(
    userId: string,
    args: { tradeId: string; accountId: string; label: JournalLabel; note?: string | null },
  ): Promise<{ ok: true }> {
    await this.brokerTradesService.labelTrade(userId, args);
    return { ok: true };
  }

  getJournalAnalytics(userId: string, query: { accountId: string; from?: string; to?: string }): Promise<JournalAnalytics> {
    return this.brokerTradesService.getAnalytics(userId, query);
  }
}

/**
 * engine/core/cache.ts
 * ====================
 * Layer B — Cache engine with 3 states:
 *   FRESH    → return cached data
 *   STALE    → return cached data + background refresh
 *   MISS     → fetch new data
 */

export type CacheState = 'fresh' | 'stale' | 'miss';

interface CacheEntry<T> {
  data: T;
  fetchedAt: number;
  expiresAt: number;   // fresh until
  staleAt: number;     // stale until (then evicted)
  key: string;
}

export interface CacheResult<T> {
  data: T;
  state: CacheState;
}

export class CacheEngine {
  private cache = new Map<string, CacheEntry<any>>();
  private maxSize: number;
  private stats = {
    hits: 0,
    misses: 0,
    staleServes: 0,
    evictions: 0
  };

  constructor(maxSize = 10000) {
    this.maxSize = maxSize;
  }

  /**
   * Get from cache or execute fetcher.
   */
  async getOrFetch<T>(
    key: string,
    ttlMs: number,
    staleWhileRevalidate: boolean,
    fetcher: () => Promise<T>
  ): Promise<CacheResult<T>> {
    const now = Date.now();
    const cached = this.cache.get(key);

    // FRESH
    if (cached && now < cached.expiresAt) {
      this.stats.hits++;
      return { data: cached.data, state: 'fresh' };
    }

    // STALE — serve cached + background refresh
    if (cached && staleWhileRevalidate && now < cached.staleAt) {
      this.stats.staleServes++;
      this.backgroundRefresh(key, ttlMs, staleWhileRevalidate, fetcher);
      return { data: cached.data, state: 'stale' };
    }

    // MISS
    this.stats.misses++;
    try {
      const data = await fetcher();
      this.set(key, data, ttlMs, staleWhileRevalidate);
      return { data, state: 'miss' };
    } catch (e) {
      // Last-good fallback: if we have cached data still within stale window, return it.
      if (cached && now < cached.staleAt) {
        this.stats.staleServes++;
        return { data: cached.data, state: 'stale' };
      }
      throw e;
    }
  }

  /**
   * Get without fetching (peek).
   */
  peek<T>(key: string): T | undefined {
    const cached = this.cache.get(key);
    if (cached && Date.now() < cached.expiresAt) {
      return cached.data;
    }
    return undefined;
  }

  /**
   * Manually set cache entry.
   */
  set<T>(key: string, data: T, ttlMs: number, staleWhileRevalidate = false): void {
    const now = Date.now();

    // Evict oldest if at capacity
    if (this.cache.size >= this.maxSize) {
      const oldest = Array.from(this.cache.entries())
        .sort((a, b) => a[1].fetchedAt - b[1].fetchedAt)[0];
      if (oldest) {
        this.cache.delete(oldest[0]);
        this.stats.evictions++;
      }
    }

    this.cache.set(key, {
      data,
      fetchedAt: now,
      expiresAt: now + ttlMs,
      staleAt: staleWhileRevalidate ? now + ttlMs * 2 : now + ttlMs,
      key
    });
  }

  /**
   * Invalidate by pattern or all.
   */
  invalidate(pattern?: string): void {
    if (!pattern) {
      this.cache.clear();
      return;
    }
    for (const [key] of this.cache) {
      if (key.includes(pattern)) this.cache.delete(key);
    }
  }

  getStats() {
    return { ...this.stats, size: this.cache.size };
  }

  private async backgroundRefresh<T>(
    key: string,
    ttlMs: number,
    staleWhileRevalidate: boolean,
    fetcher: () => Promise<T>
  ): Promise<void> {
    try {
      const data = await fetcher();
      this.set(key, data, ttlMs, staleWhileRevalidate);
    } catch {
      // Background refresh failed — stale data remains until eviction
    }
  }
}

/**
 * engine/core/dedupe.ts
 * =====================
 * Inflight request deduplication.
 * If 4 widgets request the same data simultaneously, only 1 API call is made.
 */

interface InflightRequest<T> {
  promise: Promise<T>;
  timestamp: number;
}

export class InflightDeduper {
  private inflight = new Map<string, InflightRequest<any>>();
  private maxAgeMs: number;
  private stats = { dedupes: 0 };

  constructor(maxAgeMs = 30000) {
    this.maxAgeMs = maxAgeMs;
  }

  /**
   * Execute fetcher, or return existing inflight promise if same key is already in flight.
   */
  async dedupe<T>(key: string, fetcher: () => Promise<T>): Promise<T> {
    const existing = this.inflight.get(key);
    const now = Date.now();

    if (existing && now - existing.timestamp < this.maxAgeMs) {
      this.stats.dedupes++;
      return existing.promise;
    }

    const promise = fetcher().finally(() => {
      this.inflight.delete(key);
    });

    this.inflight.set(key, { promise, timestamp: now });
    return promise;
  }

  getStats(): { dedupes: number; active: number } {
    return { dedupes: this.stats.dedupes, active: this.inflight.size };
  }

  clear(): void {
    this.inflight.clear();
  }
}

export interface AISStreamConfig {
  apiKey: string;
}

export class AISStreamProvider {
  private apiKey: string;

  constructor(config: AISStreamConfig) {
    this.apiKey = config.apiKey;
  }

  async fetchSnapshot(): Promise<any[]> {
    if (!this.apiKey) throw new Error('missing_aisstream_api_key');

    const ws = new WebSocket('wss://stream.aisstream.io/v0/stream');
    const messages: any[] = [];

    const done = new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(() => {
        try {
          ws.close();
        } catch {
          // ignore
        }
        resolve();
      }, 2500);

      ws.onopen = () => {
        const subscriptionMessage = {
          APIKey: this.apiKey,
          BoundingBoxes: [
            // Strait of Hormuz
            [[24.5, 54.6], [26.9, 57.6]],
            // Suez Canal
            [[29.2, 31.0], [31.6, 33.2]],
            // Bab-el-Mandeb
            [[11.8, 41.5], [13.6, 43.7]],
          ],
          FilterMessageTypes: ['PositionReport', 'ShipStaticData'],
        };
        ws.send(JSON.stringify(subscriptionMessage));
      };

      ws.onmessage = (evt) => {
        try {
          const json = JSON.parse(String(evt.data));
          messages.push(json);
          if (messages.length >= 120) {
            clearTimeout(timeout);
            try {
              ws.close();
            } catch {
              // ignore
            }
            resolve();
          }
        } catch {
          // ignore
        }
      };

      ws.onerror = () => {
        clearTimeout(timeout);
        reject(new Error('aisstream_ws_error'));
      };
    });

    await done;
    return messages;
  }
}

/**
 * engine/providers/finnhub.ts
 * ===========================
 * Finnhub provider (news).
 *
 * Endpoints:
 * - /company-news?symbol={symbol}&from={YYYY-MM-DD}&to={YYYY-MM-DD}&token=...
 */

const BASE_URL = 'https://finnhub.io/api/v1';

export interface FinnhubConfig {
  apiKey: string;
}

export class FinnhubProvider {
  private apiKey: string;

  constructor(config: FinnhubConfig) {
    this.apiKey = config.apiKey;
  }

  async fetchNews(symbol: string, limit: number = 10): Promise<any[]> {
    const to = new Date();
    const from = new Date(Date.now() - 7 * 86400000);
    const toStr = to.toISOString().slice(0, 10);
    const fromStr = from.toISOString().slice(0, 10);

    const url =
      `${BASE_URL}/company-news?symbol=${encodeURIComponent(symbol)}` +
      `&from=${encodeURIComponent(fromStr)}` +
      `&to=${encodeURIComponent(toStr)}` +
      `&token=${encodeURIComponent(this.apiKey)}`;

    const res = await fetch(url);
    if (!res.ok) throw new Error(`Finnhub news error: ${res.status}`);
    const json = await res.json();
    if (!Array.isArray(json)) throw new Error('Finnhub: invalid news response');
    return json.slice(0, limit);
  }
}

/**
 * engine/providers/fmp.ts
 * =======================
 * Financial Modeling Prep provider.
 * ONLY fetches raw data. No normalization, no caching, no routing.
 * Free tier: 250 requests/day [^16^]
 * 
 * Endpoints:
 *   - /quote/{symbol}
 *   - /stock_news?tickers={symbol}
 *   - /profile/{symbol}
 *   - /technical_indicator/1day/{symbol}
 */

const BASE_URL = 'https://financialmodelingprep.com/api/v3';

export interface FMPConfig {
  apiKey: string;
}

export class FMPProvider {
  private apiKey: string;

  constructor(config: FMPConfig) {
    this.apiKey = config.apiKey;
  }

  /**
   * Fetch raw stock quote.
   */
  async fetchQuote(symbol: string): Promise<any> {
    const url = `${BASE_URL}/quote/${symbol}?apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP quote error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data) || data.length === 0) throw new Error('FMP: empty quote response');
    return data[0];
  }

  /**
   * Fetch raw news.
   */
  async fetchNews(symbol: string, limit: number = 10): Promise<any[]> {
    const url = `${BASE_URL}/stock_news?tickers=${symbol}&limit=${limit}&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP news error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid news response');
    return data;
  }

  /**
   * Fetch raw company profile.
   */
  async fetchProfile(symbol: string): Promise<any> {
    const url = `${BASE_URL}/profile/${symbol}?apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP profile error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data) || data.length === 0) throw new Error('FMP: empty profile response');
    return data[0];
  }

  /**
   * Fetch raw technical indicator.
   */
  async fetchTechnical(symbol: string, indicator: string = 'rsi', period: number = 14): Promise<any[]> {
    const url = `${BASE_URL}/technical_indicator/1day/${symbol}?type=${indicator}&period=${period}&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP technical error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid technical response');
    return data;
  }

  async fetchAnalystTargets(symbol: string): Promise<any[]> {
    const url = `https://financialmodelingprep.com/api/v4/price-target-consensus?symbol=${encodeURIComponent(symbol)}&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP targets error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid targets response');
    return data;
  }

  async fetchAnalystRecommendations(symbol: string): Promise<any[]> {
    const url = `${BASE_URL}/analyst-stock-recommendations/${encodeURIComponent(symbol)}?apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP recs error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid recs response');
    return data;
  }

  async fetchUpgradesDowngrades(symbol: string): Promise<any[]> {
    const url = `https://financialmodelingprep.com/api/v4/upgrades-downgrades?symbol=${encodeURIComponent(symbol)}&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP upgrades error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid upgrades response');
    return data;
  }

  async fetchStockPeers(symbol: string): Promise<any[]> {
    const url = `https://financialmodelingprep.com/api/v4/stock_peers?symbol=${encodeURIComponent(symbol)}&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP peers error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid peers response');
    return data;
  }

  async fetchHistoricalLine(symbol: string): Promise<any> {
    if (!this.apiKey?.trim()) throw new Error('FMP: missing api key');
    const enc = encodeURIComponent(symbol);
    const stable = `https://financialmodelingprep.com/stable/historical-chart/1day/${enc}?apikey=${encodeURIComponent(this.apiKey)}`;
    const resStable = await fetch(stable);
    if (resStable.ok) {
      const arr = await resStable.json();
      if (Array.isArray(arr) && arr.length > 0) return { historical: arr };
    }
    const url = `${BASE_URL}/historical-price-full/${enc}?serietype=line&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP historical error: ${res.status}`);
    const data = await res.json();
    if (data && Array.isArray(data.historical) && data.historical.length > 0) return data;
    if (Array.isArray(data) && data.length > 0) return { historical: data };
    throw new Error('FMP: empty historical response');
  }

  /**
   * Fetch raw earnings calendar rows for a date range.
   * Dates must be YYYY-MM-DD.
   */
  async fetchEarningsCalendar(from: string, to: string): Promise<any[]> {
    const url = `${BASE_URL}/earning_calendar?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&apikey=${this.apiKey}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FMP earnings error: ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('FMP: invalid earnings response');
    return data;
  }
}

/**
 * engine/providers/fred.ts
 * ========================
 * FRED (Federal Reserve Economic Data) provider.
 * ONLY fetches raw macro data. No normalization.
 * Free tier: 120 requests/day [^4^]
 * 
 * Series IDs:
 *   - CPIAUCSL → CPI (Consumer Price Index)
 *   - UNRATE → Unemployment Rate
 *   - FEDFUNDS → Federal Funds Rate
 *   - GDP → Gross Domestic Product
 *   - DGS10 → 10-Year Treasury Rate
 */

const BASE_URL = 'https://api.stlouisfed.org/fred';

export interface FREDConfig {
  apiKey: string;
}

export class FREDProvider {
  private apiKey: string;

  constructor(config: FREDConfig) {
    this.apiKey = config.apiKey;
  }

  /**
   * Fetch raw series data.
   */
  async fetchSeries(seriesId: string, from?: string, to?: string): Promise<any> {
    const params = new URLSearchParams({
      series_id: seriesId,
      api_key: this.apiKey,
      file_type: 'json',
      sort_order: 'desc',
      limit: '1000'
    });
    if (from) params.set('observation_start', from);
    if (to) params.set('observation_end', to);

    const url = `${BASE_URL}/series/observations?${params}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FRED series error: ${res.status}`);
    const data = await res.json();
    if (!data.observations) throw new Error('FRED: no observations');
    return data;
  }

  /**
   * Fetch series info (name, description, frequency).
   */
  async fetchSeriesInfo(seriesId: string): Promise<any> {
    const url = `${BASE_URL}/series?series_id=${seriesId}&api_key=${this.apiKey}&file_type=json`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`FRED info error: ${res.status}`);
    const data = await res.json();
    const seriesList = data.seriess ?? data.seriemos;
    if (!Array.isArray(seriesList) || seriesList.length === 0) throw new Error('FRED: no series info');
    return seriesList[0];
  }
}

