/**
 * engine/services/accountService.ts
 * ==================================
 * Account service — user truth from Supabase.
 * 
 * Flow:
 *   1. Check cache (short TTL — account changes frequently)
 *   2. Fetch from Supabase (no fallback — Supabase IS the truth)
 *   3. Normalize to AccountSummary / Position[] / WatchlistItem[]
 *   4. Return fixed shape
 * 
 * NO fallback — Supabase is the single source of truth for user data.
 */

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import type { SourcePolicy } from '../core/policies';
import { DEFAULT_POLICIES } from '../core/policies';
import type { AccountSummary, Position, WatchlistItem } from '../types/account';
import { SupabaseProvider } from '../providers/supabase';

export interface AccountProviderConfig {
  id: string;
  provider: SupabaseProvider;
  weight: number;
}

export class AccountService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private health: ProviderHealthTracker;
  private providers: Map<string, AccountProviderConfig>;
  private policy: SourcePolicy;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: AccountProviderConfig[]
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.health = health;
    this.providers = new Map(configs.map(c => [c.id, c]));
    this.policy = DEFAULT_POLICIES.account;

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: 'supabase',
        weight: config.weight,
        monthlyLimit: Infinity,
        dailyLimit: 0,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: 50,
        dataQuality: 1.0
      });
    }
  }

  /**
   * Get account summary — the ONLY function the UI calls for account data.
   */
  async getSummary(userId: string): Promise<AccountSummary> {
    const cacheKey = `account:summary:${userId}`;

    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchSummary(userId))
    );

    return result.data as AccountSummary;
  }

  /**
   * Get open positions.
   */
  async getOpenPositions(userId: string): Promise<Position[]> {
    const cacheKey = `account:positions:${userId}`;

    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchPositions(userId))
    );

    return result.data as Position[];
  }

  /**
   * Get watchlist.
   */
  async getWatchlist(userId: string): Promise<WatchlistItem[]> {
    const cacheKey = `account:watchlist:${userId}`;

    const result = await this.cache.getOrFetch(
      cacheKey,
      15000,  // 15 seconds for watchlist
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchWatchlist(userId))
    );

    return result.data as WatchlistItem[];
  }

  // --- Private fetchers ---

  private async fetchSummary(userId: string): Promise<AccountSummary> {
    const config = this.providers.get('supabase_1');
    if (!config) throw new Error('No Supabase provider configured');

    try {
      const raw = await config.provider.fetchAccount(userId);
      this.health.recordSuccess('supabase_1');

      if (!raw) {
        return {
          userId,
          balance: 0,
          equity: 0,
          marginUsed: 0,
          marginAvailable: 0,
          openPnl: 0,
          closedPnl: 0,
          currency: 'USD',
          lastUpdated: new Date().toISOString(),
        };
      }

      return {
        userId,
        balance: raw.balance || 0,
        equity: raw.equity || 0,
        marginUsed: raw.margin_used || 0,
        marginAvailable: raw.margin_available || 0,
        openPnl: raw.open_pnl || 0,
        closedPnl: raw.closed_pnl || 0,
        currency: raw.currency || 'USD',
        lastUpdated: raw.updated_at || new Date().toISOString()
      };
    } catch (e) {
      this.health.recordFailure('supabase_1', e);
      throw e;
    }
  }

  private async fetchPositions(userId: string): Promise<Position[]> {
    const config = this.providers.get('supabase_1');
    if (!config) throw new Error('No Supabase provider configured');

    try {
      const raw = await config.provider.fetchPositions(userId);
      this.health.recordSuccess('supabase_1');

      return raw.map((p: any) => ({
        id: p.id,
        symbol: p.symbol,
        direction: p.direction,
        size: p.size,
        entryPrice: p.entry_price,
        currentPrice: p.current_price,
        stopLoss: p.stop_loss,
        takeProfit: p.take_profit,
        pnl: p.pnl,
        pnlPercent: p.pnl_percent,
        margin: p.margin,
        openedAt: p.opened_at
      }));
    } catch (e) {
      this.health.recordFailure('supabase_1', e);
      throw e;
    }
  }

  private async fetchWatchlist(userId: string): Promise<WatchlistItem[]> {
    const config = this.providers.get('supabase_1');
    if (!config) throw new Error('No Supabase provider configured');

    try {
      const raw = await config.provider.fetchWatchlist(userId);
      this.health.recordSuccess('supabase_1');

      return raw.map((w: any) => ({
        symbol: w.symbol,
        name: w.name,
        price: w.price || 0,
        change: w.change || 0,
        changePercent: w.change_percent || 0,
        volume: w.volume,
        high24h: w.high_24h,
        low24h: w.low_24h,
        alerts: w.alerts || []
      }));
    } catch (e) {
      this.health.recordFailure('supabase_1', e);
      throw e;
    }
  }
}

/**
 * engine/services/axeService.ts
 * =============================
 * Axe (AI assistant) service — combines Supabase memory + technical analysis.
 * 
 * Flow:
 *   1. Fetch memory from Supabase (user truth)
 *   2. Fetch chart data for technical analysis
 *   3. Calculate key levels, patterns, signals
 *   4. Merge with memory
 *   5. Return fixed AxeContext shape
 * 
 * Supabase = memory truth. Analysis = computed context.
 */

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import type { SourcePolicy } from '../core/policies';
import { DEFAULT_POLICIES } from '../core/policies';
import type { AxeContext, AxeMemoryItem, AxeStatus, KeyLevel, Pattern, Signal } from '../types/axe';
import { SupabaseProvider } from '../providers/supabase';
import { ChartService } from './chartService';

export interface AxeProviderConfig {
  id: string;
  provider: SupabaseProvider;
  weight: number;
}

export class AxeService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private health: ProviderHealthTracker;
  private providers: Map<string, AxeProviderConfig>;
  private policy: SourcePolicy;
  private chartService: ChartService;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    chartService: ChartService,
    configs: AxeProviderConfig[]
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.health = health;
    this.chartService = chartService;
    this.providers = new Map(configs.map(c => [c.id, c]));
    this.policy = DEFAULT_POLICIES.axe;

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: 'supabase',
        weight: config.weight,
        monthlyLimit: Infinity,
        dailyLimit: 0,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: 50,
        dataQuality: 1.0
      });
    }
  }

  /**
   * Get Axe context for a symbol — the ONLY function the UI calls for Axe analysis.
   */
  async getContext(symbol: string, timeframe: string, userId: string): Promise<AxeContext> {
    const normSymbol = Normalizer.symbol(symbol);
    const normTf = Normalizer.timeframe(timeframe);
    const cacheKey = Normalizer.cacheKey('axe', { symbol: normSymbol, tf: normTf, userId });

    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.buildContext(normSymbol, normTf, userId))
    );

    return result.data as AxeContext;
  }

  /**
   * Get Axe memory for user.
   */
  async getMemory(userId: string, symbol?: string): Promise<AxeMemoryItem[]> {
    const cacheKey = Normalizer.cacheKey('axe_memory', { userId, symbol });

    const result = await this.cache.getOrFetch(
      cacheKey,
      10000,  // 10 seconds
      false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchMemory(userId, symbol))
    );

    return result.data as AxeMemoryItem[];
  }

  /**
   * Get Axe status (online, active symbols, pending alerts).
   */
  async getStatus(userId: string): Promise<AxeStatus> {
    const memory = await this.getMemory(userId);
    const pendingAlerts = memory.filter(m => m.type === 'alert' && !m.resolvedAt).length;
    const activeSymbols = [
      ...new Set(
        memory
          .map((m) => m.symbol)
          .filter((s): s is string => typeof s === 'string' && s.length > 0),
      ),
    ];

    return {
      isOnline: true,
      lastActivity: memory[0]?.createdAt || new Date().toISOString(),
      activeSymbols,
      pendingAlerts,
      memoryCount: memory.length
    };
  }

  // --- Private builders ---

  private async buildContext(symbol: string, timeframe: string, userId: string): Promise<AxeContext> {
    // 1. Fetch memory from Supabase
    const memory = await this.fetchMemory(userId, symbol);

    // 2. Fetch chart for technical analysis
    const chart = await this.chartService.getChart(symbol, timeframe);

    // 3. Calculate key levels
    const keyLevels = this.calculateKeyLevels(chart);

    // 4. Detect patterns
    const patterns = this.detectPatterns(chart);

    // 5. Generate signals
    const signals = this.generateSignals(chart, keyLevels);

    // 6. Determine bias
    const { bias, confidence } = this.calculateBias(signals, patterns);

    // 7. Build human-readable analysis
    const analysis = this.buildAnalysis(symbol, bias, confidence, signals, keyLevels, patterns);

    return {
      symbol,
      timeframe,
      bias,
      confidence,
      keyLevels,
      patterns,
      signals,
      memory,
      lastUpdated: new Date().toISOString(),
      analysis
    };
  }

  private async fetchMemory(userId: string, symbol?: string): Promise<AxeMemoryItem[]> {
    const config = this.providers.get('supabase_1');
    if (!config) throw new Error('No Supabase provider configured');

    try {
      const raw = await config.provider.fetchAxeMemory(userId, symbol);
      this.health.recordSuccess('supabase_1');

      return raw.map((m: any) => ({
        id: m.id,
        type: m.type || 'insight',
        content: m.content,
        symbol: m.symbol,
        createdAt: m.created_at,
        resolvedAt: m.resolved_at,
        priority: m.priority || 'medium'
      }));
    } catch (e) {
      this.health.recordFailure('supabase_1', e);
      throw e;
    }
  }

  // --- Technical Analysis ---

  private calculateKeyLevels(chart: any): KeyLevel[] {
    const candles = chart.candles;
    if (candles.length < 20) return [];

    const levels: KeyLevel[] = [];
    const closes = candles.map((c: any) => c.close);
    const highs = candles.map((c: any) => c.high);
    const lows = candles.map((c: any) => c.low);

    // Recent high/low
    const recentHigh = Math.max(...highs.slice(-20));
    const recentLow = Math.min(...lows.slice(-20));
    const current = closes[closes.length - 1];

    levels.push({ price: recentHigh, type: 'resistance', strength: 0.8 });
    levels.push({ price: recentLow, type: 'support', strength: 0.8 });

    // VWAP approximation
    const vwap = candles.slice(-20).reduce((sum: number, c: any) => sum + c.close, 0) / 20;
    levels.push({ price: vwap, type: 'vwap', strength: 0.6 });

    // Psychological levels
    const round = Math.round(current / 10) * 10;
    levels.push({ price: round, type: 'psychological', strength: 0.4 });

    // Fibonacci retracement from recent swing
    const fibLevels = [0.236, 0.382, 0.5, 0.618, 0.786];
    const range = recentHigh - recentLow;
    for (const fib of fibLevels) {
      levels.push({
        price: recentHigh - range * fib,
        type: 'fibonacci',
        strength: 0.5
      });
    }

    return levels.sort((a, b) => b.strength - a.strength).slice(0, 8);
  }

  private detectPatterns(chart: any): Pattern[] {
    const candles = chart.candles;
    const patterns: Pattern[] = [];

    if (candles.length < 5) return patterns;

    const last5 = candles.slice(-5);
    const closes = last5.map((c: any) => c.close);

    // Check for trend
    const first = closes[0];
    const lastCloseBar = closes[closes.length - 1];
    const change = ((lastCloseBar - first) / first) * 100;

    if (change > 3) {
      patterns.push({
        name: 'Uptrend',
        type: 'continuation',
        confidence: Math.min(0.9, Math.abs(change) / 10),
        startTime: last5[0].time
      });
    } else if (change < -3) {
      patterns.push({
        name: 'Downtrend',
        type: 'continuation',
        confidence: Math.min(0.9, Math.abs(change) / 10),
        startTime: last5[0].time
      });
    }

    // Doji detection
    const lastCandle = last5[last5.length - 1];
    const body = Math.abs(lastCandle.close - lastCandle.open);
    const range = lastCandle.high - lastCandle.low;
    if (range > 0 && body / range < 0.1) {
      patterns.push({
        name: 'Doji',
        type: 'neutral',
        confidence: 0.7,
        startTime: lastCandle.time
      });
    }

    return patterns;
  }

  private generateSignals(chart: any, levels: KeyLevel[]): Signal[] {
    const signals: Signal[] = [];
    const candles = chart.candles;
    if (candles.length < 14) return signals;

    const closes = candles.map((c: any) => c.close);
    const lastClose = closes[closes.length - 1];
    const rsi = this.calculateRSI(closes, 14);
    const lastRSI = rsi[rsi.length - 1];

    // RSI signals
    if (!isNaN(lastRSI)) {
      if (lastRSI < 30) {
        signals.push({
          name: 'RSI Oversold',
          direction: 'bullish',
          strength: (30 - lastRSI) / 30,
          timeframe: chart.timeframe,
          indicator: 'RSI'
        });
      } else if (lastRSI > 70) {
        signals.push({
          name: 'RSI Overbought',
          direction: 'bearish',
          strength: (lastRSI - 70) / 30,
          timeframe: chart.timeframe,
          indicator: 'RSI'
        });
      }
    }

    // Price vs key levels
    for (const level of levels) {
      const distance = Math.abs(lastClose - level.price) / lastClose;
      if (distance < 0.005) {
        signals.push({
          name: `Near ${level.type}`,
          direction: lastClose > level.price ? 'bearish' : 'bullish',
          strength: level.strength,
          timeframe: chart.timeframe,
          indicator: 'Key Level'
        });
      }
    }

    return signals;
  }

  private calculateBias(signals: Signal[], patterns: Pattern[]): { bias: 'bullish' | 'bearish' | 'neutral'; confidence: number } {
    let bullishScore = 0;
    let bearishScore = 0;

    for (const signal of signals) {
      if (signal.direction === 'bullish') bullishScore += signal.strength;
      if (signal.direction === 'bearish') bearishScore += signal.strength;
    }

    for (const pattern of patterns) {
      if (pattern.type === 'continuation') {
        // Trend continuation — check direction from pattern name
        if (pattern.name.includes('Up')) bullishScore += pattern.confidence;
        if (pattern.name.includes('Down')) bearishScore += pattern.confidence;
      }
    }

    const total = bullishScore + bearishScore;
    if (total === 0) return { bias: 'neutral', confidence: 0.5 };

    const bullishRatio = bullishScore / total;
    const confidence = Math.abs(bullishRatio - 0.5) * 2;

    if (bullishRatio > 0.6) return { bias: 'bullish', confidence };
    if (bullishRatio < 0.4) return { bias: 'bearish', confidence };
    return { bias: 'neutral', confidence };
  }

  private buildAnalysis(symbol: string, bias: string, confidence: number, signals: Signal[], levels: KeyLevel[], patterns: Pattern[]): string {
    const parts: string[] = [];
    parts.push(`${symbol} is showing ${bias} signals with ${(confidence * 100).toFixed(0)}% confidence.`);

    if (signals.length > 0) {
      const topSignals = signals.slice(0, 3).map(s => s.name).join(', ');
      parts.push(`Key signals: ${topSignals}.`);
    }

    if (levels.length > 0) {
      const keyLevel = levels[0];
      parts.push(`Watch ${keyLevel.type} at ${keyLevel.price.toFixed(2)}.`);
    }

    if (patterns.length > 0) {
      parts.push(`Pattern detected: ${patterns[0].name}.`);
    }

    return parts.join(' ');
  }

  private calculateRSI(values: number[], period: number = 14): number[] {
    const result: number[] = [];
    let avgGain = 0, avgLoss = 0;

    for (let i = 1; i <= period && i < values.length; i++) {
      const change = values[i] - values[i - 1];
      if (change > 0) avgGain += change;
      else avgLoss -= change;
    }
    avgGain /= period;
    avgLoss /= period;

    for (let i = 0; i < values.length; i++) {
      if (i < period) {
        result.push(NaN);
        continue;
      }
      const rs = avgGain / (avgLoss || 1);
      result.push(100 - (100 / (1 + rs)));

      if (i < values.length - 1) {
        const change = values[i + 1] - values[i];
        avgGain = (avgGain * (period - 1) + (change > 0 ? change : 0)) / period;
        avgLoss = (avgLoss * (period - 1) + (change < 0 ? -change : 0)) / period;
      }
    }
    return result;
  }
}

/**
 * engine/services/brokerTradesService.ts
 * =====================================
 * Broker accounts + trades + journal label workflow.
 *
 * Truth lives in Supabase tables:
 * - user_broker_accounts
 * - broker_trades
 * - trade_journal_labels
 * - user_workspace_preferences.active_account_id
 */

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { SupabaseProvider } from '../providers/supabase';
import type { BrokerAccount, BrokerTrade, JournalAnalytics, JournalLabel, TradeHistoryQuery } from '../types/broker';

function hex(bytes: ArrayBuffer): string {
  const u8 = new Uint8Array(bytes);
  return Array.from(u8)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

async function sha256Hex(input: string): Promise<string> {
  const buf = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest('SHA-256', buf);
  return hex(digest);
}

function newLinkToken(): string {
  // Token is displayed once; only hash is stored.
  const rand = typeof crypto !== 'undefined' && 'randomUUID' in crypto ? crypto.randomUUID() : `t_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  return `axe_${rand}`;
}

export class BrokerTradesService {
  constructor(
    private cache: CacheEngine,
    private deduper: InflightDeduper,
    private supabase: SupabaseProvider,
  ) {}

  async listAccounts(userId: string): Promise<BrokerAccount[]> {
    const cacheKey = `broker:accounts:${userId}`;
    const result = await this.cache.getOrFetch(cacheKey, 5000, true, () =>
      this.deduper.dedupe(cacheKey, () => this.supabase.listBrokerAccounts(userId)),
    );
    return result.data as BrokerAccount[];
  }

  async createAccount(
    userId: string,
    args: { label: string; mt5Login?: string; mt5Server?: string },
  ): Promise<{ account: BrokerAccount; linkToken: string }> {
    const token = newLinkToken();
    const tokenHash = await sha256Hex(token);
    const account = await this.supabase.insertBrokerAccount({
      userId,
      provider: 'mt5',
      label: args.label || 'MT5 Account',
      mt5Login: args.mt5Login,
      mt5Server: args.mt5Server,
      linkTokenHash: tokenHash,
    });
    // Invalidate account cache.
    this.cache.invalidate(`broker:accounts:${userId}`);
    return { account, linkToken: token };
  }

  async setActiveAccount(userId: string, accountId: string | null): Promise<void> {
    await this.supabase.setActiveAccount(userId, accountId);
    // Preferences are cached client-side; no cache here.
  }

  async getTradeHistory(
    userId: string,
    query: TradeHistoryQuery,
  ): Promise<{ trades: BrokerTrade[]; labelsByTradeId: Record<string, { label: JournalLabel; note?: string | null; updatedAt: string }> }> {
    const cacheKey = `broker:trades:${userId}:${query.accountId}:${query.from ?? ''}:${query.to ?? ''}:${query.symbol ?? ''}:${query.label ?? ''}:${query.limit ?? ''}`;
    const result = await this.cache.getOrFetch(cacheKey, 4000, true, () =>
      this.deduper.dedupe(cacheKey, () => this.supabase.fetchTradeHistory(userId, query)),
    );
    return result.data as any;
  }

  async labelTrade(userId: string, args: { tradeId: string; accountId: string; label: JournalLabel; note?: string | null }): Promise<void> {
    await this.supabase.upsertTradeLabel({ userId, ...args });
    // Labels affect analytics and trade history; clear broad caches for this user.
    this.cache.invalidate(`broker:trades:${userId}:`);
    this.cache.invalidate(`broker:analytics:${userId}:`);
  }

  async getAnalytics(userId: string, query: { accountId: string; from?: string; to?: string }): Promise<JournalAnalytics> {
    const cacheKey = `broker:analytics:${userId}:${query.accountId}:${query.from ?? ''}:${query.to ?? ''}`;
    const result = await this.cache.getOrFetch(cacheKey, 5000, true, () =>
      this.deduper.dedupe(cacheKey, () => this.supabase.getJournalAnalytics(userId, query)),
    );
    return result.data as JournalAnalytics;
  }
}

/**
 * engine/services/chartService.ts
 * ===============================
 * Chart service — fetches OHLC candles from multiple providers.
 *
 * Order: Polygon → Twelve Data → FMP → optional Yahoo (only when `EngineConfig.enableYahooChartFallback` is true).
 * Per-provider symbols (e.g. XAUUSD → C:XAUUSD, XAU/USD) via chartSymbolRouting.
 */

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import type { SourcePolicy } from '../core/policies';
import { DEFAULT_POLICIES } from '../core/policies';
import type { ChartData, Candle, ChartFetchDebugMeta } from '../types/chart';
import { ChartFetchError } from '../types/chart';
import { PolygonProvider } from '../providers/polygon';
import { TwelveDataProvider } from '../providers/twelvedata';
import { YahooFinanceProvider } from '../providers/yahoo';
import { FMPProvider } from '../providers/fmp';
import { withRetry } from '../core/retry';
import { costUnits } from '../core/cost';
import { resolveChartSymbolRouting } from '../chartSymbolRouting';

export interface ChartCredentialFlags {
  polygon: boolean;
  twelvedata: boolean;
  fmp: boolean;
  /** Opt-in: Yahoo registered as last chart provider. */
  yahooChartFallbackEnabled: boolean;
}

export interface ChartProviderConfig {
  id: string;
  provider: PolygonProvider | TwelveDataProvider | YahooFinanceProvider | FMPProvider;
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  supportedTimeframes: string[];
  costPerCall?: number;
}

function sourceLabelFromProviderId(id: string): string {
  if (id.startsWith('chart_polygon')) return 'Polygon';
  if (id.startsWith('chart_twelvedata')) return 'TwelveData';
  if (id.startsWith('chart_fmp') || id.startsWith('fmp_chart')) return 'FMP';
  if (id.startsWith('yahoo')) return 'YahooFinance';
  return id;
}

export class ChartService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private providers: Map<string, ChartProviderConfig>;
  private policy: SourcePolicy;
  private chartCreds: ChartCredentialFlags;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: ChartProviderConfig[],
    chartCreds?: ChartCredentialFlags,
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.providers = new Map(configs.map((c) => [c.id, c]));
    this.policy = DEFAULT_POLICIES.chart;
    this.chartCreds = chartCreds ?? {
      polygon: false,
      twelvedata: false,
      fmp: false,
      yahooChartFallbackEnabled: false,
    };

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  async getChart(symbol: string, timeframe: string, limit?: number): Promise<ChartData> {
    const normSymbol = Normalizer.symbol(symbol);
    const normTf = Normalizer.timeframe(timeframe);
    const cacheKey = Normalizer.cacheKey('chart', { symbol: normSymbol, tf: normTf, limit });

    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchFromProviders(normSymbol, normTf, limit)),
    );

    return result.data as ChartData;
  }

  /** Polygon → TwelveData → FMP → Yahoo. Legacy ids (fmp_chart_*) still tier correctly. */
  private sortChartProviderIds(ids: string[]): string[] {
    const tier = (id: string): number => {
      if (id.startsWith('chart_polygon') || id.startsWith('polygon_chart')) return 0;
      if (id.startsWith('chart_twelvedata') || id.startsWith('twelvedata_chart')) return 1;
      if (id.startsWith('chart_fmp') || id.startsWith('fmp_chart')) return 2;
      if (id.startsWith('yahoo')) return 3;
      return 9;
    };
    return [...ids].sort((a, b) => tier(a) - tier(b) || a.localeCompare(b));
  }

  private aggregateFromTo(timeframe: string, limit?: number): { from: string; to: string } {
    const to = new Date().toISOString().split('T')[0];
    const L = Math.max(5, limit ?? 100);
    let calDays: number;
    if (timeframe === '1D' || timeframe === '3D') {
      calDays = Math.min(3650, Math.ceil(L * 2.5));
    } else if (timeframe === '1W') {
      calDays = Math.min(3650, L * 14);
    } else if (timeframe === '1MO') {
      calDays = Math.min(3650, 40 * L);
    } else {
      calDays = Math.min(730, Math.max(7, Math.ceil(L / 8) + 14));
    }
    const from = new Date(Date.now() - calDays * 86400000).toISOString().split('T')[0];
    return { from, to };
  }

  private timeframeToYahoo(tf: string, limit?: number): [string, string] {
    const map: Record<string, [string, string]> = {
      '1M': ['1m', '1d'],
      '5M': ['5m', '5d'],
      '15M': ['15m', '5d'],
      '1H': ['1h', '1mo'],
      '4H': ['1h', '3mo'],
      '1D': ['1d', '6mo'],
      '1W': ['1wk', '1y'],
      '1MO': ['1mo', '5y'],
    };
    const base = map[tf] || ['1d', '1mo'];
    if (tf === '1D' && (limit ?? 0) >= 90) {
      return ['1d', '2y'];
    }
    return base;
  }

  private async fetchFromProviders(symbol: string, timeframe: string, limit?: number): Promise<ChartData> {
    const routing = resolveChartSymbolRouting(symbol);
    const notes: string[] = [];
    const debug: ChartFetchDebugMeta = {
      providersAttempted: [],
      providerErrors: {},
      configured: {
        polygon: this.chartCreds.polygon,
        twelvedata: this.chartCreds.twelvedata,
        fmp: this.chartCreds.fmp,
      },
      yahooChartFallbackEnabled: this.chartCreds.yahooChartFallbackEnabled,
      providerSymbol: {},
      finalProviderUsed: null,
      candleCount: 0,
      notes,
    };

    const capableProviders = Array.from(this.providers.entries())
      .filter(([, config]) => config.supportedTimeframes.includes(timeframe))
      .map(([id]) => id);

    if (capableProviders.length === 0) {
      throw new ChartFetchError(`No provider supports timeframe: ${timeframe}`, debug);
    }

    const sorted = this.sortChartProviderIds(capableProviders);
    const chain = sorted.filter((id) => {
      if (id.startsWith('yahoo')) {
        const ok = this.health.isHealthy(id);
        if (!ok) notes.push(`yahoo_skipped_unhealthy:${id}`);
        return ok;
      }
      return true;
    });

    if (chain.length === 0) {
      notes.push('no_healthy_chart_provider_for_timeframe');
      throw new ChartFetchError('No healthy chart provider available', debug);
    }

    let lastError: Error | null = null;
    let sawYahoo429 = false;

    for (let i = 0; i < chain.length; i++) {
      const id = chain[i];
      const config = this.providers.get(id);
      if (!config) continue;

      debug.providersAttempted.push(id);

      const runOne = async (): Promise<{ raw: unknown; symUsed: string }> => {
        const providerKind = id.split('_')[0];
        if (config.provider instanceof PolygonProvider) {
          this.router.recordUsage(id, costUnits({ domain: 'chart', provider: providerKind, endpoint: 'fetchAggregates' }));
          const multiplier = this.timeframeToMultiplier(timeframe);
          const timespan = this.timeframeToTimespan(timeframe);
          const { from, to } = this.aggregateFromTo(timeframe, limit);
          const raw = await config.provider.fetchAggregates(routing.polygon, multiplier, timespan, from, to);
          return { raw, symUsed: routing.polygon };
        }
        if (config.provider instanceof TwelveDataProvider) {
          this.router.recordUsage(id, costUnits({ domain: 'chart', provider: providerKind, endpoint: 'fetchTimeSeries' }));
          const interval = this.timeframeToTwelveDataInterval(timeframe);
          const raw = await config.provider.fetchTimeSeries(routing.twelvedata, interval, limit || 100);
          return { raw, symUsed: routing.twelvedata };
        }
        if (config.provider instanceof FMPProvider) {
          this.router.recordUsage(id, costUnits({ domain: 'chart', provider: 'fmp', endpoint: 'fetchHistoricalLine' }));
          let lastInner: unknown = null;
          for (const fmpSym of routing.fmp) {
            try {
              const raw = await config.provider.fetchHistoricalLine(fmpSym);
              return { raw, symUsed: fmpSym };
            } catch (ie) {
              lastInner = ie;
            }
          }
          throw lastInner instanceof Error ? lastInner : new Error(String(lastInner));
        }
        if (config.provider instanceof YahooFinanceProvider) {
          this.router.recordUsage(id, costUnits({ domain: 'chart', provider: 'yahoo', endpoint: 'fetchYahooChart' }));
          const [interval, range] = this.timeframeToYahoo(timeframe, limit);
          const raw = await config.provider.fetchChart(routing.yahoo, interval, range);
          return { raw, symUsed: routing.yahoo };
        }
        throw new Error('Unsupported chart provider');
      };

      try {
        if (i > 0) this.router.recordFallbackUsed();
        const { value: pack } = await withRetry(async () => runOne(), {
          maxAttempts: 2,
          baseDelayMs: 150,
          maxDelayMs: 900,
        });
        const { raw, symUsed } = pack;
        debug.providerSymbol[id] = symUsed;

        const displaySource = sourceLabelFromProviderId(id);
        const chart = this.normalizeChart(symbol, timeframe, raw, displaySource, limit);
        if (chart.candles.length === 0) {
          throw new Error('empty_candles_after_normalize');
        }

        this.health.recordSuccess(id);
        chart.debug = {
          ...debug,
          finalProviderUsed: id,
          candleCount: chart.candles.length,
          providerSymbol: { ...debug.providerSymbol, [id]: symUsed },
        };
        return chart;
      } catch (e) {
        const err = e instanceof Error ? e : new Error(String(e));
        lastError = err;
        const msg = err.message;
        debug.providerErrors[id] = msg;
        if (id.startsWith('yahoo') && /\b429\b/.test(msg)) {
          sawYahoo429 = true;
        }
        this.health.recordFailure(id, e);
      }
    }

    const priorConfigured =
      this.chartCreds.polygon || this.chartCreds.twelvedata || this.chartCreds.fmp;
    if (sawYahoo429 && priorConfigured) {
      throw new ChartFetchError(
        'yahoo_429_after_configured_providers_failed',
        { ...debug, finalProviderUsed: null, candleCount: 0, notes },
      );
    }

    if (lastError instanceof ChartFetchError) throw lastError;
    throw new ChartFetchError(lastError?.message ?? 'chart_all_providers_failed', {
      ...debug,
      finalProviderUsed: null,
      candleCount: 0,
      notes,
    });
  }

  private normalizeChart(symbol: string, timeframe: string, raw: any, sourceName: string, limit?: number): ChartData {
    let candles: Candle[] = [];

    if (raw.results) {
      candles = raw.results.map((r: any) => ({
        time: new Date(r.t).toISOString(),
        open: r.o,
        high: r.h,
        low: r.l,
        close: r.c,
        volume: r.v,
      }));
    } else if (raw.values) {
      candles = raw.values
        .map((v: any) => ({
          time: v.datetime,
          open: parseFloat(v.open),
          high: parseFloat(v.high),
          low: parseFloat(v.low),
          close: parseFloat(v.close),
          volume: Number(v.volume) || 0,
        }))
        .reverse();
    } else if (Array.isArray(raw?.historical)) {
      const hist = raw.historical as any[];
      candles = [...hist]
        .reverse()
        .map((h: any) => ({
          time: String(h.date ?? h.formattedDate ?? '').includes('T')
            ? String(h.date)
            : `${String(h.date ?? '')}T00:00:00.000Z`,
          open: Number(h.open ?? h.adjOpen ?? 0),
          high: Number(h.high ?? h.adjHigh ?? 0),
          low: Number(h.low ?? h.adjLow ?? 0),
          close: Number(h.close ?? h.adjClose ?? 0),
          volume: Number(h.volume ?? 0),
        }))
        .filter((c) => Number.isFinite(c.close) && c.time);
    } else if (Array.isArray(raw)) {
      candles = [...raw]
        .reverse()
        .map((h: any) => ({
          time: String(h.date ?? h.formattedDate ?? '').includes('T')
            ? String(h.date)
            : `${String(h.date ?? '')}T00:00:00.000Z`,
          open: Number(h.open ?? h.adjOpen ?? 0),
          high: Number(h.high ?? h.adjHigh ?? 0),
          low: Number(h.low ?? h.adjLow ?? 0),
          close: Number(h.close ?? h.adjClose ?? 0),
          volume: Number(h.volume ?? 0),
        }))
        .filter((c) => Number.isFinite(c.close) && c.time);
    } else if (raw.timestamp && raw.indicators?.quote?.[0]) {
      const q = raw.indicators.quote[0];
      candles = raw.timestamp
        .map((t: number, i: number) => ({
          time: new Date(t * 1000).toISOString(),
          open: q.open[i],
          high: q.high[i],
          low: q.low[i],
          close: q.close[i],
          volume: raw.indicators.volume?.[0]?.[i] || 0,
        }))
        .filter((c: Candle) => c.close !== null);
    }

    const cap = typeof limit === 'number' && limit > 0 ? limit : candles.length;
    if (candles.length > cap) {
      candles = candles.slice(-cap);
    }

    const indicators: Record<string, number[]> = {};
    if (candles.length >= 14) {
      indicators.sma20 = this.calculateSMA(
        candles.map((c) => c.close),
        20,
      );
      indicators.rsi = this.calculateRSI(
        candles.map((c) => c.close),
        14,
      );
    }

    return {
      symbol,
      timeframe,
      candles,
      indicators,
      source: sourceName.replace('Provider', ''),
    };
  }

  private timeframeToMultiplier(tf: string): number {
    const map: Record<string, number> = { '1M': 1, '5M': 5, '15M': 15, '30M': 30, '1H': 1, '4H': 4, '1D': 1 };
    return map[tf] || 1;
  }

  private timeframeToTimespan(tf: string): string {
    if (tf.endsWith('M')) return 'minute';
    if (tf.endsWith('H')) return 'hour';
    if (tf === '1D' || tf === '3D') return 'day';
    if (tf === '1W') return 'week';
    if (tf === '1MO') return 'month';
    return 'day';
  }

  private timeframeToTwelveDataInterval(tf: string): string {
    const map: Record<string, string> = {
      '1M': '1min',
      '5M': '5min',
      '15M': '15min',
      '30M': '30min',
      '1H': '1h',
      '2H': '2h',
      '4H': '4h',
      '1D': '1day',
      '1W': '1week',
      '1MO': '1month',
    };
    return map[tf] || '1day';
  }

  private calculateSMA(values: number[], period: number): number[] {
    const result: number[] = [];
    for (let i = 0; i < values.length; i++) {
      if (i < period - 1) {
        result.push(NaN);
        continue;
      }
      const sum = values.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0);
      result.push(sum / period);
    }
    return result;
  }

  private calculateRSI(values: number[], period: number = 14): number[] {
    const result: number[] = [];
    let gains = 0,
      losses = 0;

    for (let i = 1; i <= period; i++) {
      const change = values[i] - values[i - 1];
      if (change > 0) gains += change;
      else losses -= change;
    }

    let avgGain = gains / period;
    let avgLoss = losses / period;

    for (let i = 0; i < values.length; i++) {
      if (i < period) {
        result.push(NaN);
        continue;
      }
      const rs = avgGain / (avgLoss || 1);
      result.push(100 - 100 / (1 + rs));

      if (i < values.length - 1) {
        const change = values[i + 1] - values[i];
        const gain = change > 0 ? change : 0;
        const loss = change < 0 ? -change : 0;
        avgGain = (avgGain * (period - 1) + gain) / period;
        avgLoss = (avgLoss * (period - 1) + loss) / period;
      }
    }
    return result;
  }
}

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import { DEFAULT_POLICIES } from '../core/policies';
import type { SourcePolicy } from '../core/policies';
import { withRetry } from '../core/retry';
import { costUnits } from '../core/cost';
import type {
  AnalystConsensusData,
  AnalystActionType,
  RelativePerformanceData,
  KeyLevelsData,
  SentimentShortData,
} from '../types/context';
import { FMPProvider } from '../providers/fmp';

export interface ContextProviderConfig {
  id: string;
  provider: FMPProvider;
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  costPerCall?: number;
}

export class ContextService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private providers: Map<string, ContextProviderConfig>;
  private policy: SourcePolicy;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: ContextProviderConfig[],
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.providers = new Map(configs.map((c) => [c.id, c]));
    this.policy = DEFAULT_POLICIES.news;

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  async getAnalystConsensus(symbol: string): Promise<AnalystConsensusData | null> {
    const sym = Normalizer.symbol(symbol);
    const cacheKey = Normalizer.cacheKey('context_analyst', { sym });
    const result = await this.cache.getOrFetch(
      cacheKey,
      300_000,
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchAnalystConsensus(sym)),
    );
    return (result.data as AnalystConsensusData | null) ?? null;
  }

  async getRelativePerformance(symbol: string): Promise<RelativePerformanceData | null> {
    const sym = Normalizer.symbol(symbol);
    const cacheKey = Normalizer.cacheKey('context_peers', { sym });
    const result = await this.cache.getOrFetch(
      cacheKey,
      120_000,
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchRelativePerformance(sym)),
    );
    return (result.data as RelativePerformanceData | null) ?? null;
  }

  async getKeyLevels(symbol: string): Promise<KeyLevelsData | null> {
    const sym = Normalizer.symbol(symbol);
    const cacheKey = Normalizer.cacheKey('context_levels', { sym });
    const result = await this.cache.getOrFetch(
      cacheKey,
      120_000,
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchKeyLevels(sym)),
    );
    return (result.data as KeyLevelsData | null) ?? null;
  }

  async getSentimentShort(symbol: string): Promise<SentimentShortData | null> {
    const sym = Normalizer.symbol(symbol);
    const cacheKey = Normalizer.cacheKey('context_sentiment', { sym });
    const result = await this.cache.getOrFetch(
      cacheKey,
      300_000,
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchSentimentShort(sym)),
    );
    return (result.data as SentimentShortData | null) ?? null;
  }

  private selectChain(): { chain: string[]; primaryId: string } {
    const providerIds = Array.from(this.providers.keys());
    const primaryId = this.router.select(providerIds, this.policy.priority);
    if (!primaryId) throw new Error('No healthy context provider available');
    const chain = this.router.buildFallbackChain(primaryId, providerIds, this.policy.fallback);
    return { chain, primaryId };
  }

  private mapAction(action: string, row: any): AnalystActionType {
    const a = String(action || '').toLowerCase();
    if (a.includes('upgrade')) return 'upgrade';
    if (a.includes('downgrade')) return 'downgrade';
    if (a.includes('init')) return 'initiate';
    if (a.includes('raise')) return 'target_raised';
    if (a.includes('lower')) return 'target_lowered';
    if (row?.priceTarget != null || row?.previousPriceTarget != null) return 'reiterate';
    return 'reiterate';
  }

  private async fetchAnalystConsensus(symbol: string): Promise<AnalystConsensusData | null> {
    const { chain, primaryId } = this.selectChain();
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const { value: [targets, recs, quote, upgrades] } = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'news', provider: 'fmp', endpoint: 'fetchQuote' }));
            return await Promise.all([
              config.provider.fetchAnalystTargets(symbol),
              config.provider.fetchAnalystRecommendations(symbol),
              config.provider.fetchQuote(symbol).then((q) => [q]).catch(() => []),
              config.provider.fetchUpgradesDowngrades(symbol),
            ]);
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 900 },
        );

        this.health.recordSuccess(id);

        const t = Array.isArray(targets) ? targets[0] : null;
        const r = Array.isArray(recs) ? recs[0] : null;
        const q = Array.isArray(quote) ? quote[0] : null;
        if (!t && !r) return null;

        const currentPrice = Number(q?.price ?? 0) || 0;

        const recentActions = (upgrades ?? []).slice(0, 12).map((u: any, i: number) => ({
          id: String(u.publishedDate ?? i) + String(u.newsPublisher ?? ''),
          firm: u.gradingCompany ?? u.analystCompany ?? 'Unknown',
          action: this.mapAction(u.action, u),
          fromRating: u.previousGrade ?? null,
          toRating: u.newGrade ?? null,
          fromTarget: u.priceWhenPosted ?? null,
          toTarget: u.priceTarget ?? null,
          publishedAt: u.publishedDate ? Date.parse(u.publishedDate) : Date.now(),
          url: u.newsURL ?? null,
        }));

        return {
          symbol,
          currentPrice,
          target: {
            average: Number(t?.targetConsensus ?? 0) || 0,
            low: Number(t?.targetLow ?? 0) || 0,
            high: Number(t?.targetHigh ?? 0) || 0,
            median: t?.targetMedian != null ? Number(t.targetMedian) : undefined,
            numberOfAnalysts: Number(t?.numberOfAnalysts ?? 0) || 0,
          },
          ratings: {
            strongBuy: Number(r?.analystRatingsStrongBuy ?? 0) || 0,
            buy: Number(r?.analystRatingsbuy ?? r?.analystRatingsBuy ?? 0) || 0,
            hold: Number(r?.analystRatingsHold ?? 0) || 0,
            sell: Number(r?.analystRatingsSell ?? 0) || 0,
            strongSell: Number(r?.analystRatingsStrongSell ?? 0) || 0,
          },
          recentActions,
        };
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    if (lastError) throw lastError;
    return null;
  }

  private async fetchRelativePerformance(symbol: string): Promise<RelativePerformanceData | null> {
    const { chain, primaryId } = this.selectChain();
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const peersRes = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'news', provider: 'fmp', endpoint: 'fetchQuote' }));
            return await config.provider.fetchStockPeers(symbol);
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 900 },
        );
        this.health.recordSuccess(id);

        const peersArr = (peersRes?.value?.[0]?.peersList ?? []).slice(0, 6);
        const tickers = [symbol, ...peersArr, 'SPY'];

        const quotes = await config.provider.fetchQuote(tickers.join(',')).catch(async () => {
          // fallback: try multiple quotes by calling v3 /quote with comma list (same endpoint supports list)
          const url = `https://financialmodelingprep.com/api/v3/quote/${tickers.join(',')}?apikey=${(config.provider as any).apiKey ?? ''}`;
          const res = await fetch(url);
          if (!res.ok) return [];
          return res.json();
        });

        const quoteList = Array.isArray(quotes) ? quotes : [];
        if (!quoteList.length) return null;
        const byTicker: Record<string, any> = Object.fromEntries(quoteList.map((q: any) => [q.symbol, q]));
        const selected = byTicker[symbol];
        const benchQ = byTicker['SPY'];

        const peers = peersArr
          .map((p: string) => byTicker[p])
          .filter(Boolean)
          .map((q: any) => ({
            symbol: q.symbol,
            name: q.name ?? q.symbol,
            changePercent: q.changesPercentage ?? 0,
            price: q.price ?? 0,
          }));

        const sectorAverage = peers.length
          ? peers.reduce((sum: number, p: any) => sum + (p.changePercent || 0), 0) / peers.length
          : undefined;

        return {
          symbol,
          sectorName: selected?.sector ?? undefined,
          benchmark: benchQ ? { symbol: benchQ.symbol, changePercent: benchQ.changesPercentage ?? 0 } : undefined,
          sectorAverage,
          peers: [
            {
              symbol,
              name: selected?.name ?? symbol,
              changePercent: selected?.changesPercentage ?? 0,
              price: selected?.price ?? 0,
              isSelected: true,
            },
            ...peers,
          ],
        };
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    if (lastError) throw lastError;
    return null;
  }

  private async fetchKeyLevels(symbol: string): Promise<KeyLevelsData | null> {
    const { chain, primaryId } = this.selectChain();
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const { value: [quoteArr, rsi, sma20, sma50, sma200, hist] } = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'news', provider: 'fmp', endpoint: 'fetchQuote' }));
            return await Promise.all([
              config.provider.fetchQuote(symbol).then((q) => [q]).catch(() => []),
              config.provider.fetchTechnical(symbol, 'rsi', 14).catch(() => []),
              config.provider.fetchTechnical(symbol, 'sma', 20).catch(() => []),
              config.provider.fetchTechnical(symbol, 'sma', 50).catch(() => []),
              config.provider.fetchTechnical(symbol, 'sma', 200).catch(() => []),
              config.provider.fetchHistoricalLine(symbol).catch(() => ({ historical: [] })),
            ]);
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 900 },
        );
        this.health.recordSuccess(id);

        const q = Array.isArray(quoteArr) ? quoteArr[0] : null;
        if (!q) return null;
        const price = Number(q.price ?? 0) || 0;
        const hi52 = q.yearHigh != null ? Number(q.yearHigh) : 0;
        const lo52 = q.yearLow != null ? Number(q.yearLow) : 0;

        const historical = (hist as any)?.historical ?? [];
        const ath = Array.isArray(historical)
          ? historical.reduce((m: number, row: any) => Math.max(m, Number(row.close ?? row.price ?? 0) || 0), 0) || undefined
          : undefined;

        const ma = (res: any[], period: number) => {
          const row = Array.isArray(res) ? res[0] : null;
          if (!row) return null;
          const value = Number(row.sma ?? row.value ?? 0) || 0;
          if (!value) return null;
          return { period, value, distancePercent: price ? ((price - value) / value) * 100 : 0 };
        };

        const mas = [ma(sma20 as any, 20), ma(sma50 as any, 50), ma(sma200 as any, 200)].filter(Boolean) as any[];
        const rsiRow = Array.isArray(rsi) ? rsi[0] : null;
        const rsiVal = rsiRow?.rsi != null ? Number(rsiRow.rsi) : null;

        const indicators: any[] = [];
        if (rsiVal != null) {
          indicators.push({
            name: 'RSI-14',
            value: rsiVal,
            signal: rsiVal >= 70 ? 'overbought' : rsiVal <= 30 ? 'oversold' : 'neutral',
          });
        }

        const levels: any[] = [];
        if (hi52) {
          levels.push({ kind: 'resistance', label: '52W high', price: hi52, distancePercent: price ? ((hi52 - price) / price) * 100 : undefined });
        }
        mas.forEach((m) => {
          levels.push({
            kind: price >= m.value ? 'support' : 'resistance',
            label: `${m.period}MA`,
            price: m.value,
            distancePercent: price ? ((m.value - price) / price) * 100 : undefined,
          });
        });
        if (lo52) {
          levels.push({ kind: 'support', label: '52W low', price: lo52, distancePercent: price ? ((lo52 - price) / price) * 100 : undefined });
        }

        return {
          symbol,
          currentPrice: price,
          week52Low: lo52,
          week52High: hi52,
          ath,
          drawdownFromAth: ath && price ? ((price - ath) / ath) * 100 : undefined,
          movingAverages: mas,
          indicators,
          levels,
        };
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    if (lastError) throw lastError;
    return null;
  }

  private async fetchSentimentShort(symbol: string): Promise<SentimentShortData | null> {
    // Minimal “non-stub” implementation: derive from FMP profile + recent news sentiment score
    // without introducing new providers yet.
    const { chain, primaryId } = this.selectChain();
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed();

        const { value: [profile, news] } = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'news', provider: 'fmp', endpoint: 'fetchProfile' as any }));
            return await Promise.all([
              config.provider.fetchProfile(symbol).catch(() => null),
              config.provider.fetchNews(symbol, 30).catch(() => []),
            ]);
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 900 },
        );
        this.health.recordSuccess(id);

        const shortPercent = profile && typeof profile.shortPercentFloat === 'number' ? profile.shortPercentFloat : undefined;
        const shortShares = profile && typeof profile.sharesShort === 'number' ? profile.sharesShort : undefined;

        // crude sentiment from titles
        const items = Array.isArray(news) ? news : [];
        const bullishWords = ['surge', 'rally', 'gain', 'beat', 'strong', 'breakout', 'upgrade'];
        const bearishWords = ['drop', 'fall', 'miss', 'weak', 'downgrade', 'crash', 'selloff'];
        let bull = 0, bear = 0, neutral = 0;
        for (const n of items) {
          const t = String(n.title ?? n.headline ?? '').toLowerCase();
          const b1 = bullishWords.some((w) => t.includes(w));
          const b2 = bearishWords.some((w) => t.includes(w));
          if (b1 && !b2) bull += 1;
          else if (b2 && !b1) bear += 1;
          else neutral += 1;
        }
        const total = bull + bear + neutral || 1;
        const score = (bull - bear) / total;

        const squeezeScore =
          shortPercent != null
            ? Math.max(0, Math.min(100, Math.round(shortPercent * 2)))
            : undefined;

        return {
          symbol,
          squeezeScore,
          shortInterest: {
            shortPercentOfFloat: shortPercent,
            shortSharesOutstanding: shortShares,
          },
          newsSentiment: {
            score,
            bullishCount: bull,
            bearishCount: bear,
            neutralCount: neutral,
            windowHours: 24,
          },
        };
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    if (lastError) throw lastError;
    return null;
  }
}

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import type { SourcePolicy } from '../core/policies';
import { DEFAULT_POLICIES } from '../core/policies';
import { withRetry } from '../core/retry';
import { costUnits } from '../core/cost';
import type { EarningsEvent, EarningsImpact } from '../types/earnings';
import { FMPProvider } from '../providers/fmp';

export interface EarningsProviderConfig {
  id: string;
  provider: FMPProvider;
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  costPerCall?: number;
}

export class EarningsService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private providers: Map<string, EarningsProviderConfig>;
  private policy: SourcePolicy;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: EarningsProviderConfig[],
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.providers = new Map(configs.map((c) => [c.id, c]));
    this.policy = DEFAULT_POLICIES.earnings ?? DEFAULT_POLICIES.news;

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  async getEarningsCalendar(from: string, to: string): Promise<EarningsEvent[]> {
    const f = String(from || '').slice(0, 10);
    const t = String(to || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(f) || !/^\d{4}-\d{2}-\d{2}$/.test(t)) {
      throw new Error('invalid_earnings_date_range');
    }

    const cacheKey = Normalizer.cacheKey('earnings', { from: f, to: t });
    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchFromProviders(f, t)),
    );

    return result.data as EarningsEvent[];
  }

  private async fetchFromProviders(from: string, to: string): Promise<EarningsEvent[]> {
    const providerIds = Array.from(this.providers.keys());
    const primaryId = this.router.select(providerIds, this.policy.priority);
    if (!primaryId) throw new Error('No healthy earnings provider available');

    const chain = this.router.buildFallbackChain(primaryId, providerIds, this.policy.fallback);
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const raw = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'earnings', provider: id.split('_')[0], endpoint: 'fetchEarningsCalendar' }));
            return await config.provider.fetchEarningsCalendar(from, to);
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 900 },
        );
        this.health.recordSuccess(id);
        return this.normalize(raw.value);
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    throw lastError || new Error('All earnings providers failed');
  }

  private normalize(rows: any[]): EarningsEvent[] {
    return (rows ?? []).map((r: any) => {
      const ticker = String(r.symbol || r.ticker || '').toUpperCase();
      const date = String(r.date || r.earningsDate || r.fiscalDateEnding || '').slice(0, 10);
      const timeRaw = String(r.time || r.timeOfDay || '').toUpperCase();
      const time: EarningsEvent['time'] =
        timeRaw === 'BMO' || timeRaw === 'AMC' || timeRaw === 'DMT' ? timeRaw : 'TBD';

      const epsEstimate = r.epsEstimated ?? r.epsEstimate ?? null;
      const epsActual = r.eps ?? r.epsActual ?? null;
      const revEstimate = r.revenueEstimated ?? r.revenueEstimate ?? null;
      const revActual = r.revenue ?? r.revenueActual ?? null;

      const epsSurprise =
        typeof epsEstimate === 'number' && typeof epsActual === 'number' ? epsActual - epsEstimate : null;
      const revenueSurprise =
        typeof revEstimate === 'number' && typeof revActual === 'number' ? revActual - revEstimate : null;

      const impact: EarningsImpact =
        (r.impact as EarningsImpact) ||
        (typeof r.marketCap === 'number' && r.marketCap > 50e9 ? 'high' : typeof r.marketCap === 'number' && r.marketCap > 10e9 ? 'medium' : 'low');

      return {
        ticker,
        company: String(r.company || r.companyName || ticker),
        date,
        time,
        sector: String(r.sector || '—'),
        marketCap: typeof r.marketCap === 'number' ? r.marketCap : 0,
        epsEstimate: typeof epsEstimate === 'number' ? epsEstimate : null,
        revenueEstimate: typeof revEstimate === 'number' ? revEstimate : null,
        epsActual: typeof epsActual === 'number' ? epsActual : null,
        revenueActual: typeof revActual === 'number' ? revActual : null,
        epsSurprise,
        revenueSurprise,
        impact,
      };
    }).filter((e) => e.ticker && e.date);
  }
}

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import { DEFAULT_POLICIES } from '../core/policies';
import type { SourcePolicy } from '../core/policies';
import { withRetry } from '../core/retry';
import { costUnits } from '../core/cost';
import type { JetPosition, Vessel, VesselAlert } from '../types/intel';
import { OpenSkyProvider } from '../providers/opensky';
import { AISStreamProvider } from '../providers/aisstream';

export interface JetProviderConfig {
  id: string;
  provider: OpenSkyProvider;
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  costPerCall?: number;
}

export interface VesselProviderConfig {
  id: string;
  provider: AISStreamProvider;
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  costPerCall?: number;
}

export class IntelService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private policy: SourcePolicy;
  private jetProviders: Map<string, JetProviderConfig>;
  private vesselProviders: Map<string, VesselProviderConfig>;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    jets: JetProviderConfig[],
    vessels: VesselProviderConfig[],
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.policy = DEFAULT_POLICIES.scanner; // fast + fallback
    this.jetProviders = new Map(jets.map((c) => [c.id, c]));
    this.vesselProviders = new Map(vessels.map((c) => [c.id, c]));

    for (const config of jets) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
    for (const config of vessels) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  async getCorporateJets(): Promise<JetPosition[]> {
    const cacheKey = Normalizer.cacheKey('intel_jets', {});
    const result = await this.cache.getOrFetch(
      cacheKey,
      60_000,
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchJets()),
    );
    return (result.data as JetPosition[]) ?? [];
  }

  async getVesselStream(): Promise<{ vessels: Vessel[]; alerts: VesselAlert[] }> {
    const cacheKey = Normalizer.cacheKey('intel_vessels', {});
    const result = await this.cache.getOrFetch(
      cacheKey,
      60_000,
      true,
      () => this.deduper.dedupe(cacheKey, () => this.fetchVessels()),
    );
    return (result.data as { vessels: Vessel[]; alerts: VesselAlert[] }) ?? { vessels: [], alerts: [] };
  }

  private selectChain<T>(m: Map<string, T>): { chain: string[]; primaryId: string } {
    const ids = Array.from(m.keys());
    const primaryId = this.router.select(ids, this.policy.priority);
    if (!primaryId) throw new Error('No healthy intel provider available');
    const chain = this.router.buildFallbackChain(primaryId, ids, this.policy.fallback);
    return { chain, primaryId };
  }

  private async fetchJets(): Promise<JetPosition[]> {
    const { chain, primaryId } = this.selectChain(this.jetProviders);
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.jetProviders.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed('intel_jets');
        const { value: states } = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'intel', provider: id.split('_')[0], endpoint: 'fetchStatesAll' as any }));
            return await config.provider.fetchStatesAll();
          },
          { maxAttempts: 2, baseDelayMs: 200, maxDelayMs: 1200 },
        );
        this.health.recordSuccess(id);
        return this.mapOpenSky(states);
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    throw lastError || new Error('All jet providers failed');
  }

  private mapOpenSky(states: any[]): JetPosition[] {
    const now = new Date().toISOString();
    const out: JetPosition[] = [];
    for (const s of (states ?? []).slice(0, 20)) {
      const icao24 = String(s?.[0] ?? '').trim();
      const callsign = String(s?.[1] ?? '').trim() || 'UNKNOWN';
      const country = String(s?.[2] ?? '').trim() || 'Unknown';
      const lon = Number(s?.[5]);
      const lat = Number(s?.[6]);
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
      const altitudeM = Number(s?.[7]);
      const speedMs = Number(s?.[9]);
      out.push({
        icao24: icao24 || `icao_${Math.random().toString(16).slice(2)}`,
        company: country,
        ticker: '—',
        aircraft: callsign,
        lat,
        lon,
        altitude: Number.isFinite(altitudeM) ? Math.round(altitudeM * 3.28084) : 0,
        speed: Number.isFinite(speedMs) ? Math.round(speedMs * 1.94384) : 0,
        origin: '—',
        destination: '—',
        departureTime: now,
        eta: '—',
        signal: 'normal',
        route: '—',
      });
    }
    return out;
  }

  private async fetchVessels(): Promise<{ vessels: Vessel[]; alerts: VesselAlert[] }> {
    const { chain, primaryId } = this.selectChain(this.vesselProviders);
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.vesselProviders.get(id);
      if (!config) continue;
      try {
        if (id !== primaryId) this.router.recordFallbackUsed('intel_vessels');
        const { value: events } = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'intel', provider: id.split('_')[0], endpoint: 'fetchSnapshot' as any }));
            return await config.provider.fetchSnapshot();
          },
          { maxAttempts: 2, baseDelayMs: 200, maxDelayMs: 1200 },
        );
        this.health.recordSuccess(id);
        return this.mapAis(events);
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    throw lastError || new Error('All vessel providers failed');
  }

  private mapAis(events: any[]): { vessels: Vessel[]; alerts: VesselAlert[] } {
    const byMmsi = new Map<string, any>();

    for (const e of events ?? []) {
      const meta = e?.Metadata ?? {};
      const msgType = String(e?.MessageType ?? '');
      const mmsi = String(meta?.MMSI ?? meta?.UserID ?? meta?.ShipMMSI ?? '');
      if (!mmsi) continue;

      const lat = Number(meta?.Latitude);
      const lon = Number(meta?.Longitude);
      const speed = Number(meta?.Sog ?? meta?.Speed ?? 0);
      const name =
        String(meta?.ShipName ?? '') ||
        String(e?.Message?.ShipStaticData?.ShipName ?? '') ||
        `Vessel ${mmsi}`;
      const type =
        String(meta?.ShipType ?? '') ||
        String(e?.Message?.ShipStaticData?.ShipType ?? '') ||
        'Vessel';
      const destination = String(meta?.Destination ?? e?.Message?.ShipStaticData?.Destination ?? '—') || '—';
      const eta = String(meta?.Eta ?? e?.Message?.ShipStaticData?.Eta ?? '—') || '—';

      const prev = byMmsi.get(mmsi) ?? {
        mmsi,
        name,
        type,
        lat: Number.isFinite(lat) ? lat : 0,
        lon: Number.isFinite(lon) ? lon : 0,
        speed: Number.isFinite(speed) ? speed : 0,
        destination,
        status: 'in_transit',
        eta,
      };

      if (Number.isFinite(lat)) prev.lat = lat;
      if (Number.isFinite(lon)) prev.lon = lon;
      if (Number.isFinite(speed)) prev.speed = speed;
      if (name) prev.name = name;
      if (type) prev.type = type;
      if (destination) prev.destination = destination;
      if (eta) prev.eta = eta;

      if (prev.speed <= 0.2) prev.status = 'anchored';
      else if (prev.speed <= 1.0) prev.status = 'loitering';
      else prev.status = 'in_transit';

      prev.__sawPosition = prev.__sawPosition || msgType === 'PositionReport';
      byMmsi.set(mmsi, prev);
    }

    const vessels: Vessel[] = Array.from(byMmsi.values())
      .map((v) => {
        if (!v.__sawPosition) v.status = 'ais_gap';
        delete v.__sawPosition;
        return v;
      })
      .filter((v) => Number.isFinite(v.lat) && Number.isFinite(v.lon))
      .slice(0, 30);

    const alerts: VesselAlert[] = [];
    const loitering = vessels.filter((v) => v.status === 'loitering').length;
    const gaps = vessels.filter((v) => v.status === 'ais_gap').length;
    if (loitering > 8) {
      alerts.push({ id: 'loitering', message: `${loitering} vessels loitering in chokepoints`, category: 'GLOBAL TRADE', severity: 'high', timestamp: 'live' });
    }
    if (gaps > 4) {
      alerts.push({ id: 'ais_gap', message: `${gaps} vessels with AIS gaps`, category: 'GLOBAL TRADE', severity: 'medium', timestamp: 'live' });
    }

    return { vessels, alerts };
  }
}

