};

function inferFredSeriesMeta(key: string): { fred: string; name: string; unit: string; frequency: MacroSeries['frequency'] } | null {
  const k = key.trim();
  if (!/^[A-Z0-9._]+$/.test(k)) return null;
  return { fred: k, name: k, unit: '', frequency: 'monthly' };
}

export class MacroService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private providers: Map<string, MacroProviderConfig>;
  private policy: SourcePolicy;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: MacroProviderConfig[]
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.providers = new Map(configs.map(c => [c.id, c]));
    this.policy = DEFAULT_POLICIES.macro;

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  /**
   * Get macro series — the ONLY function the UI calls for macro data.
   */
  async getSeries(key: string, filter: MacroFilter = {}): Promise<MacroSeries> {
    const seriesInfo = SERIES_MAP[key] ?? inferFredSeriesMeta(key);
    if (!seriesInfo) {
      throw new Error(`Unknown macro series: ${key}`);
    }

    const range = Normalizer.dateRange(filter.range);
    const cacheKey = Normalizer.cacheKey('macro', { key, from: range.from, to: range.to });

    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchFromProviders(key, range.from, range.to))
    );

    return result.data as MacroSeries;
  }

  /**
   * List available macro series.
   */
  listAvailableSeries(): { key: string; name: string; unit: string; frequency: string }[] {
    return Object.entries(SERIES_MAP).map(([key, info]) => ({
      key,
      name: info.name,
      unit: info.unit,
      frequency: info.frequency
    }));
  }

  /**
   * Fetch from providers with failover.
   */
  private async fetchFromProviders(key: string, from: string, to: string): Promise<MacroSeries> {
    const seriesInfo = SERIES_MAP[key] ?? inferFredSeriesMeta(key);
    if (!seriesInfo) throw new Error(`Unknown macro series: ${key}`);
    const providerIds = Array.from(this.providers.keys());
    const primaryId = this.router.select(providerIds, this.policy.priority);

    if (!primaryId) {
      throw new Error('No healthy macro provider available');
    }

    const chain = this.router.buildFallbackChain(primaryId, providerIds, this.policy.fallback);
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;

      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const raw = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'macro', provider: id.split('_')[0], endpoint: 'fetchSeries' }));
            if (config.provider instanceof FREDProvider) {
              return await config.provider.fetchSeries(seriesInfo.fred, from, to);
            }
            return await config.provider.fetchMacro(key, from, to);
          },
          { maxAttempts: 2, baseDelayMs: 200, maxDelayMs: 1200 },
        );

        this.health.recordSuccess(id);
        return this.normalizeMacro(key, raw.value, seriesInfo);
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    throw lastError || new Error('All macro providers failed');
  }

  /**
   * Normalize raw FRED data to fixed MacroSeries shape.
   */
  private normalizeMacro(key: string, raw: any, info: typeof SERIES_MAP[string]): MacroSeries {
    const observations = raw.observations || [];

    // Parse and sort by date
    const points: MacroDataPoint[] = observations
      .map((obs: any) => ({
        date: obs.date,
        value: obs.value === '.' ? NaN : parseFloat(obs.value)
      }))
      .filter((p: MacroDataPoint) => !isNaN(p.value))
      .sort((a: MacroDataPoint, b: MacroDataPoint) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Calculate changes
    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1].value;
      const curr = points[i].value;
      points[i].change = curr - prev;
      points[i].changePercent = prev !== 0 ? ((curr - prev) / Math.abs(prev)) * 100 : 0;
    }

    return {
      key,
      name: info.name,
      description: `${info.name} — ${info.frequency} data`,
      unit: info.unit,
      frequency: info.frequency,
      data: points,
      lastUpdated: new Date().toISOString()
    };
  }
}

/**
 * engine/services/newsService.ts
 * ==============================
 * News service — chooses provider, fallback, cache, normalize.
 * 
 * Flow:
 *   1. Normalize input (symbol uppercase)
 *   2. Check cache
 *   3. Select best provider (FMP → Financial Juice)
 *   4. Fetch with failover
 *   5. Normalize to NewsItem[]
 *   6. Deduplicate by URL
 *   7. Enrich (sentiment, importance)
 *   8. Return fixed shape
 */

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import type { SourcePolicy } from '../core/policies';
import { DEFAULT_POLICIES } from '../core/policies';
import type { NewsItem, NewsFilter } from '../types/news';
import { FMPProvider } from '../providers/fmp';
import { withRetry } from '../core/retry';
import { costUnits } from '../core/cost';

export interface NewsProviderConfig {
  id: string;
  provider: FMPProvider | any;  // Extend with other news providers
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  costPerCall?: number;
}

export class NewsService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private providers: Map<string, NewsProviderConfig>;
  private policy: SourcePolicy;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: NewsProviderConfig[]
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.providers = new Map(configs.map(c => [c.id, c]));
    this.policy = DEFAULT_POLICIES.news;

    // Register providers with router
    for (const config of configs) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  /**
   * Get news — the ONLY function the UI calls for news.
   */
  async getNews(filter: NewsFilter = {}): Promise<NewsItem[]> {
    const symbol = filter.symbol ? Normalizer.symbol(filter.symbol) : undefined;
    const cacheKey = Normalizer.cacheKey('news', { symbol, category: filter.category, limit: filter.limit });

    // 1. Cache check + inflight dedupe
    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchFromProviders(symbol, filter))
    );

    // 2. Filter & enrich
    let items = result.data as NewsItem[];

    if (filter.sentiment) {
      items = items.filter(n => n.sentiment === filter.sentiment);
    }
    if (filter.minImportance) {
      items = items.filter(n => (n.importance || 0) >= filter.minImportance!);
    }
    if (filter.limit) {
      items = items.slice(0, filter.limit);
    }

    return items;
  }

  /**
   * Fetch from providers with failover.
   */
  private async fetchFromProviders(symbol?: string, filter?: NewsFilter): Promise<NewsItem[]> {
    const providerIds = Array.from(this.providers.keys());
    const primaryId = this.router.select(providerIds, this.policy.priority);

    if (!primaryId) {
      throw new Error('No healthy news provider available');
    }

    const chain = this.router.buildFallbackChain(primaryId, providerIds, this.policy.fallback);
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;

      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const raw = await withRetry(
          async () => {
            this.router.recordUsage(id, costUnits({ domain: 'news', provider: id.split('_')[0], endpoint: 'fetchNews' }));
            return await config.provider.fetchNews(symbol || 'AAPL', filter?.limit || 10);
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 800 },
        );
        this.health.recordSuccess(id);

        // Normalize to NewsItem[]
        const items = this.normalizeNews(raw.value, symbol);
        return items;
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    throw lastError || new Error('All news providers failed');
  }

  /**
   * Normalize raw provider data to fixed NewsItem shape.
   */
  private normalizeNews(raw: any[], symbol?: string): NewsItem[] {
    const seen = new Set<string>();

    return raw
      .map((item: any, i: number) => {
        const id = item.url || item.link || `${item.source || 'unknown'}_${i}_${Date.now()}`;
        return {
          id,
          source: item.site || item.source || 'unknown',
          title: item.title || item.headline || 'Untitled',
          summary: item.text || item.summary || item.description || undefined,
          url: item.url || item.link || undefined,
          publishedAt: item.publishedDate || item.published_at || item.datetime || new Date().toISOString(),
          symbol: symbol || item.symbol || null,
          category: item.category || null,
          sentiment: this.inferSentiment(item),
          importance: this.calculateImportance(item)
        };
      })
      .filter(item => {
        // Deduplicate by URL
        if (seen.has(item.id)) return false;
        seen.add(item.id);
        return true;
      });
  }

  /**
   * Infer sentiment from title + summary.
   */
  private inferSentiment(item: any): 'bullish' | 'bearish' | 'neutral' | null {
    const text = `${item.title || ''} ${item.text || item.summary || ''}`.toLowerCase();
    const bullish = ['surge', 'rally', 'gain', 'bull', 'up', 'rise', 'growth', 'beat', 'strong', 'moon', 'breakout'];
    const bearish = ['drop', 'fall', 'bear', 'down', 'crash', 'loss', 'miss', 'weak', 'sell', 'dump', 'recession'];

    const bCount = bullish.filter(w => text.includes(w)).length;
    const beCount = bearish.filter(w => text.includes(w)).length;

    if (bCount > beCount) return 'bullish';
    if (beCount > bCount) return 'bearish';
    if (bCount > 0 || beCount > 0) return 'neutral';
    return null;
  }

  /**
   * Calculate importance score (0-10).
   */
  private calculateImportance(item: any): number {
    let score = 5;
    if (item.title?.length > 80) score += 1;
    if (item.text?.length > 500) score += 1;
    if (item.url?.includes('bloomberg') || item.url?.includes('reuters')) score += 2;
    return Math.min(10, score);
  }
}

/**
 * engine/services/scannerService.ts
 * ==================================
 * Scanner service — aggregates market data into ranked signals.
 * 
 * Flow:
 *   1. Fetch market snapshot from multiple providers
 *   2. Calculate metrics (RSI, volume, momentum, etc.)
 *   3. Score each symbol 0-100
 *   4. Rank and filter
 *   5. Return fixed ScannerResult[]
 */

import { CacheEngine } from '../core/cache';
import { InflightDeduper } from '../core/dedupe';
import { Normalizer } from '../core/normalize';
import { SourceRouter } from '../core/router';
import { ProviderHealthTracker } from '../core/health';
import type { SourcePolicy } from '../core/policies';
import { DEFAULT_POLICIES } from '../core/policies';
import type { ScannerResult, ScannerFilter } from '../types/scanner';
import { FMPProvider } from '../providers/fmp';
import { PolygonProvider } from '../providers/polygon';
import { withRetry } from '../core/retry';
import { costUnits } from '../core/cost';

export interface ScannerProviderConfig {
  id: string;
  provider: FMPProvider | PolygonProvider;
  weight: number;
  monthlyLimit: number;
  dailyLimit: number;
  avgLatencyMs: number;
  dataQuality: number;
  costPerCall?: number;
}

export class ScannerService {
  private cache: CacheEngine;
  private deduper: InflightDeduper;
  private router: SourceRouter;
  private health: ProviderHealthTracker;
  private providers: Map<string, ScannerProviderConfig>;
  private policy: SourcePolicy;

  constructor(
    cache: CacheEngine,
    deduper: InflightDeduper,
    router: SourceRouter,
    health: ProviderHealthTracker,
    configs: ScannerProviderConfig[]
  ) {
    this.cache = cache;
    this.deduper = deduper;
    this.router = router;
    this.health = health;
    this.providers = new Map(configs.map(c => [c.id, c]));
    this.policy = DEFAULT_POLICIES.scanner;

    for (const config of configs) {
      router.register({
        id: config.id,
        provider: config.id.split('_')[0],
        weight: config.weight,
        monthlyLimit: config.monthlyLimit,
        dailyLimit: config.dailyLimit,
        usedThisMonth: 0,
        usedToday: 0,
        avgLatencyMs: config.avgLatencyMs,
        dataQuality: config.dataQuality,
        costPerCall: config.costPerCall ?? 1,
      });
    }
  }

  /**
   * Scan market — the ONLY function the UI calls for scanner/heatmap.
   */
  async scan(filter: ScannerFilter = {}): Promise<ScannerResult[]> {
    const cacheKey = Normalizer.cacheKey('scanner', filter as Record<string, unknown>);

    const result = await this.cache.getOrFetch(
      cacheKey,
      this.policy.cacheTtlMs,
      this.policy.staleWhileRevalidate || false,
      () => this.deduper.dedupe(cacheKey, () => this.fetchAndScore(filter))
    );

    let results = result.data as ScannerResult[];

    // Apply filters
    if (filter.sector) {
      results = results.filter(r => r.sector === filter.sector);
    }
    if (filter.minMarketCap) {
      results = results.filter(r => (r.marketCap || 0) >= filter.minMarketCap!);
    }
    if (filter.minScore) {
      results = results.filter(r => r.score >= filter.minScore!);
    }
    if (filter.signals) {
      results = results.filter(r => filter.signals!.some(s => r.signals.includes(s)));
    }
    if (filter.limit) {
      results = results.slice(0, filter.limit);
    }

    return results;
  }

  /**
   * Fetch raw data and score symbols.
   */
  private async fetchAndScore(filter: ScannerFilter): Promise<ScannerResult[]> {
    const providerIds = Array.from(this.providers.keys());
    const primaryId = this.router.select(providerIds, this.policy.priority);

    if (!primaryId) {
      throw new Error('No healthy scanner provider available');
    }

    const chain = this.router.buildFallbackChain(primaryId, providerIds, this.policy.fallback);
    let lastError: Error | null = null;

    for (const id of chain) {
      const config = this.providers.get(id);
      if (!config) continue;

      try {
        if (id !== primaryId) this.router.recordFallbackUsed();
        const raw = await withRetry(
          async () => {
            if (config.provider instanceof FMPProvider) {
              return await this.fetchFMPScanner(id, config.provider, filter);
            }
            if (config.provider instanceof PolygonProvider) {
              return await this.fetchPolygonScanner(id, config.provider, filter);
            }
            return [];
          },
          { maxAttempts: 2, baseDelayMs: 150, maxDelayMs: 800 },
        );

        this.health.recordSuccess(id);
        return this.scoreAndRank(raw.value);
      } catch (e) {
        lastError = e as Error;
        this.health.recordFailure(id, e);
      }
    }

    throw lastError || new Error('All scanner providers failed');
  }

  private async fetchFMPScanner(providerId: string, provider: FMPProvider, _filter: ScannerFilter): Promise<any[]> {
    // FMP doesn't have a direct screener in free tier
    // We fetch quotes for major symbols and calculate scores
    const symbols = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'META', 'NVDA', 'AMD', 'NFLX', 'SPY', 'QQQ'];
    const results: any[] = [];

    for (const symbol of symbols) {
      try {
        this.router.recordUsage(
          providerId,
          costUnits({ domain: 'scanner', provider: providerId.split('_')[0], endpoint: 'fetchQuote' }),
        );
        const quote = await provider.fetchQuote(symbol);
        results.push(quote);
      } catch {
        // Skip failed symbols
      }
    }

    return results;
  }

  private async fetchPolygonScanner(providerId: string, provider: PolygonProvider, _filter: ScannerFilter): Promise<any[]> {
    // Polygon aggregates for major symbols
    const symbols = ['AAPL', 'MSFT', 'GOOGL', 'TSLA', 'NVDA'];
    const results: any[] = [];

    for (const symbol of symbols) {
      try {
        this.router.recordUsage(
          providerId,
          costUnits({ domain: 'scanner', provider: providerId.split('_')[0], endpoint: 'fetchAggregates' }),
        );
        const agg = await provider.fetchAggregates(symbol, 1, 'day');
        if (agg.results && agg.results.length > 0) {
          results.push({ symbol, ...agg.results[agg.results.length - 1] });
        }
      } catch {
        // Skip failed symbols
      }
    }

    return results;
  }

  /**
   * Score and rank raw data into ScannerResult[].
   */
  private scoreAndRank(raw: any[]): ScannerResult[] {
    const scored = raw.map((item) => {
      const symbol = item.symbol || 'UNKNOWN';
      const price = item.price || item.c || item.close || 0;
      const change = item.change || 0;
      const changePercent = item.changesPercentage || ((change / (price - change)) * 100) || 0;
      const volume = item.volume || item.v || 0;
      const marketCap = item.marketCap || 0;

      // Calculate signals
      const signals: string[] = [];
      if (Math.abs(changePercent) > 5) signals.push('High volatility');
      if (volume > 10000000) signals.push('Volume spike');
      if (changePercent > 2) signals.push('Bullish momentum');
      if (changePercent < -2) signals.push('Bearish momentum');

      // Composite score (0-100)
      let score = 50;
      score += Math.min(25, Math.abs(changePercent) * 3);  // Volatility
      score += Math.min(15, Math.log10(volume + 1) / 2);   // Volume
      if (marketCap > 100000000000) score += 10;            // Large cap

      // Determine trend
      let trend: ScannerResult['trend'] = 'neutral';
      if (changePercent > 5) trend = 'strong_up';
      else if (changePercent > 2) trend = 'up';
      else if (changePercent < -5) trend = 'strong_down';
      else if (changePercent < -2) trend = 'down';

      return {
        symbol,
        name: item.name,
        score: Math.min(100, Math.max(0, score)),
        rank: 0,  // Set after sorting
        signals,
        metrics: [
          { name: 'Price', value: price, unit: 'USD' },
          { name: 'Change', value: changePercent, unit: '%' },
          { name: 'Volume', value: volume },
          { name: 'Market Cap', value: marketCap, unit: 'USD' }
        ],
        trend,
        sector: item.sector,
        marketCap
      };
    });

    // Sort by score descending and assign ranks
    scored.sort((a, b) => b.score - a.score);
    scored.forEach((s, i) => { s.rank = i + 1; });

    return scored;
  }
}

import { useEffect, useRef, useState, useCallback } from "react";

export function useAsync(fn, deps = []) {
  const [state, setState] = useState({ data: null, loading: true, error: null });
  const latest = useRef(0);

  const run = useCallback(() => {
    const id = ++latest.current;
    const controller = new AbortController();
    setState((s) => ({ ...s, loading: true, error: null }));
    Promise.resolve(fn(controller.signal))
      .then((data) => {
        if (id === latest.current) setState({ data, loading: false, error: null });
      })
      .catch((err) => {
        if (id === latest.current && err && err.name !== "AbortError") {
          setState({ data: null, loading: false, error: err });
        }
      });
    return () => controller.abort();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  useEffect(() => run(), [run]);

  return { ...state, refetch: run };
}

