/**
 * Maps `engineAdapter.aiDataCenters()` into the DataCenterMap module contract.
 * Data remains PLACEHOLDER until a real Supabase table is wired in the engine.
 */
import type { DataCenterDataSource, DataCenterProject, DataCenterSnapshot, ProjectCategory, RegionKey } from '@/features/datacenter-map/types';
import { aiDataCenters, type DataCenter } from './engineAdapterLegacy';

function inferCategory(operator: string): ProjectCategory {
  const o = operator.toLowerCase();
  if (o.includes('oracle') || o.includes('stargate')) return 'stargate';
  if (o.includes('microsoft') || o.includes('google') || o.includes('meta') || o.includes('amazon')) return 'hyperscaler';
  if (o.includes('coreweave') || o.includes('neocloud')) return 'neocloud';
  if (o.includes('sovereign') || o.includes('government')) return 'sovereign';
  if (o.includes('crusoe') || o.includes('independent')) return 'independent';
  return 'independent';
}

function regionFromCountry(country: string): RegionKey {
  const c = country.toUpperCase();
  if (['USA', 'CAN', 'MEX'].includes(c)) return 'n_america';
  if (['GBR', 'DEU', 'FRA', 'NLD', 'SWE', 'DNK'].includes(c)) return 'europe';
  if (['CHN', 'JPN', 'KOR', 'SGP', 'IND', 'THA'].includes(c)) return 'asia';
  if (['ARE', 'SAU', 'ISR', 'KWT'].includes(c)) return 'middle_east';
  return 'world';
}

function mapRow(dc: DataCenter): DataCenterProject {
  const country = dc.country.length === 3 ? dc.country.toUpperCase() : 'USA';
  return {
    id: dc.id,
    name: dc.name,
    company: dc.operator,
    category: inferCategory(dc.operator),
    status: dc.status,
    country,
    countryName: dc.country,
    region: regionFromCountry(country),
    city: dc.city,
    latitude: dc.lat,
    longitude: dc.lon,
    powerMw: dc.capacityMW,
    investmentUsdM: null,
    expectedYear: dc.yearOnline ? Number(String(dc.yearOnline).replace(/\D/g, '').slice(0, 4)) || null : null,
    operator: dc.operator,
    updatedAt: new Date().toISOString(),
  };
}

export function createEngineAiDataCenterDataSource(): DataCenterDataSource {
  return {
    async fetchProjects({ signal: _signal }): Promise<DataCenterSnapshot> {
      const rows = await aiDataCenters();
      return {
        projects: rows.map(mapRow),
        fetchedAt: new Date().toISOString(),
      };
    },
  };
}

import { useEffect, useMemo, useState } from 'react';
import { isSupabaseConfigured, supabase } from '@/lib/supabase';

export type JetAlertSeverity = 'info' | 'watch' | 'unusual';

export type JetAlert = {
  ticker: string;
  tail_number?: string | null;
  airport_icao?: string | null;
  landed_at?: string | null;
  reason?: string | null;
  severity: JetAlertSeverity;
  expires_at?: string | null;
};

export type JetAlertMap = Record<string, JetAlert>;

function nowIso() {
  return new Date().toISOString();
}

function stubAlerts(): JetAlert[] {
  // Placeholder until Supabase tables + Edge Function are live.
  // Keep small & deterministic so the UI doesn't feel spammy.
  return [
    {
      ticker: 'NVDA',
      tail_number: 'N123NV',
      airport_icao: 'KTEB',
      landed_at: nowIso(),
      reason: 'Unusual landing near NYC',
      severity: 'unusual',
      expires_at: new Date(Date.now() + 30 * 60_000).toISOString(),
    },
  ];
}

function buildMap(rows: JetAlert[]): JetAlertMap {
  const out: JetAlertMap = {};
  for (const r of rows) {
    const t = String(r.ticker || '').toUpperCase().trim();
    if (!t) continue;
    out[t] = { ...r, ticker: t };
  }
  return out;
}

function isExpired(a: JetAlert) {
  if (!a.expires_at) return false;
  const ts = new Date(a.expires_at).getTime();
  return Number.isFinite(ts) ? ts <= Date.now() : false;
}

export function useJetAlerts(pollMs = 60_000): { alerts: JetAlertMap; source: 'supabase' | 'stub' } {
  const [rows, setRows] = useState<JetAlert[]>([]);
  const [source, setSource] = useState<'supabase' | 'stub'>(() =>
    isSupabaseConfigured() ? 'supabase' : 'stub'
  );

  useEffect(() => {
    let alive = true;

    async function loadSupabase() {
      try {
        const { data, error } = await supabase
          .from('jet_alerts')
          .select('ticker, tail_number, airport_icao, landed_at, reason, severity, expires_at')
          .gt('expires_at', new Date().toISOString());
        if (!alive) return;
        if (error) throw error;
        setSource('supabase');
        setRows((data as any[])?.map((d) => ({ ...d, ticker: String(d.ticker || '').toUpperCase() })) ?? []);
      } catch {
        // If Supabase isn't provisioned yet (table missing) we silently fall back to stub.
        if (!alive) return;
        setSource('stub');
        setRows(stubAlerts());
      }
    }

    function load() {
      if (isSupabaseConfigured()) loadSupabase();
      else {
        setSource('stub');
        setRows(stubAlerts());
      }
    }

    load();
    const t = window.setInterval(load, pollMs);
    return () => {
      alive = false;
      window.clearInterval(t);
    };
  }, [pollMs]);

  const alerts = useMemo(() => {
    const filtered = rows.filter((a) => !isExpired(a));
    return buildMap(filtered);
  }, [rows]);

  return { alerts, source };
}

export function jetIconTone(severity: JetAlertSeverity): { fg: string; glow: string } {
  if (severity === 'unusual') return { fg: 'text-cyan-300', glow: 'shadow-[0_0_10px_rgba(34,211,238,0.35)]' };
  if (severity === 'watch') return { fg: 'text-yellow-300', glow: 'shadow-[0_0_10px_rgba(253,224,71,0.28)]' };
  return { fg: 'text-white/40', glow: 'shadow-none' };
}

import type { BarUpdateMessage, TickMessage } from './liveEngineTypes';

export type Candle = {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume?: number;
};

/**
 * Patch only the last candle in-place (or append if missing).
 * This avoids full series reloads.
 */
export function applyBarUpdate(candles: Candle[], msg: BarUpdateMessage): Candle[] {
  if (candles.length === 0) return [msg.bar];
  const last = candles[candles.length - 1];
  if (last.time === msg.bar.time) {
    const next = [...candles];
    next[next.length - 1] = { ...last, ...msg.bar };
    return next;
  }
  // If stream jumped forward (new bar), append.
  if (new Date(msg.bar.time).getTime() > new Date(last.time).getTime()) {
    return [...candles, msg.bar];
  }
  // Out-of-order update: ignore.
  return candles;
}

/**
 * Optional: use ticks to update the current candle close/high/low without reloading history.
 */
export function applyTickToOpenCandle(candles: Candle[], _msg: TickMessage): Candle[] {
  // Intentionally minimal: you typically rely on bar_update for OHLC correctness.
  return candles;
}

/**
 * Supabase Client
 *
 * Creates a Supabase client from env vars.
