                  ['G I', 'Intel'],
                  ['G M', 'Main'],
                  ['G J', 'Journal'],
                  ['G E', 'Engine Ops'],
                  ['G S', 'Market Scanner'],
                  ['G R', 'Macro Terminal'],
                  ['G A', 'Axe Companion'],
                  ['G ,', 'Settings'],
                ].map(([keys, label]) => (
                  <div
